import sys


def read(line):
    return map(int, line.strip().split())


def main():
    test = sys.stdin.readlines()
    string = test[0].strip()
    queries = [read(line) for line in test[2:]]

    accx, accy, accz = [0], [0], [0]
    out = []
    for c in string:
        accx.append(accx[-1])
        accy.append(accy[-1])
        accz.append(accz[-1])
        if c == 'x':
            accx[-1] += 1
        elif c == 'y':
            accy[-1] += 1
        else:
            accz[-1] += 1

    for l, r in queries:
        numx = accx[r] - accx[l - 1]
        numy = accy[r] - accy[l - 1]
        numz = accz[r] - accz[l - 1]

        if r - l > 1 and (abs(numx - numy) > 1 or abs(numx - numz) > 1 or
                          abs(numy - numz) > 1):
            out.append('NO')
        else:
            out.append('YES')

    print('\n'.join(out))


