	elif ord("A") <= c <= ord("Z"):
		d += c - ord("A") + 10
	elif ord("a") <= c <= ord("z"):
		d += c - ord("a") + 36
	elif ord("-") == c:
		d += 62
	else:
		d += 63

	ans *= pow(3, format(d, "06b").count("0"), 10 ** 9 + 7)
	ans %= 10 ** 9 + 7

