def get_primes(n):
    res = [2]
    arr = [True] * ((n - 1) // 2)
    i = 0
    for i in range(len(arr)):
        if arr[i]:
            a = i * 2 + 3
            res.append(a)
            for ii in range(i + a, len(arr), a):
                arr[ii] = False

    return res

