    res = ["1"] * min(n - 1, len(primes))
    left = n - 1 - len(res)
    ii = 2
    while left > 0:
        for a in primes:
            if ii * a <= n:
                res.append(str(ii))
                left -= 1
            else:
                break
            if ii % a == 0 or left == 0:
                break
        ii += 1
    print(" ".join(res))

