modulo = 10**9 + 7

def get_order(inp):
    n = len(inp)
    gt = [[-1] * i for i in range(n)]
    for j in range(i)[::-1]:
        if inp[n-1] > inp[j]:
            gt[n-1][j] = 0
    for i in range(n-1)[::-1]:
        for j in range(i)[::-1]:
            if inp[i] > inp[j]:
                gt[i][j] = 0
            elif inp[i] == inp[j]:
                pos = gt[i + 1][j + 1]
                if pos >= 0 and pos + 1 < i - j:
                    gt[i][j] = pos + 1
    return gt


def solve(inp):
    inp = tuple(map(int, inp))
    n = len(inp)

    gt = get_order(inp)

    posg = [[None]*(n+1) for _ in range(n)]
    for i in range(0, n)[::-1]:
        for l in range(1, n+1)[::-1]:
            end = i + l
            if inp[i] == 0 or end > n:
                posg[i][l] = 0
                continue
            if end + l > n:
                posg[i][l] = 1
                continue
            sameok = gt[end][i] >= 0
            res = posg[i][l+1]
            if sameok:
                res += posg[i + l][l]
            else:
                res += posg[i + l][l + 1]
            posg[i][l] = res % modulo

    return posg[0][1]


