def sumDigits(x):
    if (x == 0):
        return 0 
    return x % 10 + sumDigits(x // 10)

def create(x):
    ans = ""
    while (x >= 9):
        ans = "9" + ans 
        x -= 9 
    ans = str(x) + ans 
    return int(ans)

def create_ex(x, y):
    track = -1
    for i in range(9, x + 1, 9):
        r = x - i 
        if (r + 1 == y):
            track = i 
    if (track == -1):
        return -1 
    r = x - track
    ans = 0  
    if (r < 9):
        ans = r 
    else: 
        ans = create(r - 8) * 10 + 8 
    ans *= (10 ** (track // 9))
    ans += create(track)
    return ans 

preResult = {} 
for i in range(100):
    s = 0
    for k in range(10):
        s += sumDigits(i + k)
        if (s <= 150 and (s, k) not in preResult):
            preResult[(s, k)] = i 


pre = [[-1 for i in range(152)] for j in range(152)]

for x in range(1, 151):
    pre[x][x] = create(x) 
    if (x != 150):
        if (x < 9):
            pre[x][x + 1] = x 
        else:
            pre[x][x + 1] = create(x - 8) * 10 + 8 
    for y in range(1, x):
        pre[x][y] = create_ex(x, y)


def update(x, maybe):
    if (x == -1):
        return maybe 
    if (x > maybe):
        return maybe 
    return x 
def solve():
    n, k = input().strip().split(' ')
    n = int(n)
    k = int(k)
    if ((n, k) in preResult):
        return preResult[(n, k)]

    ans = -1 
    for st in range(10):
        rem = n 
        flag = False 
        p1 = 0
        p2 = 0
        for i in range(k + 1):
            flag = flag | (st + i > 9)
            rem -= (st + i) % 10 
            p1 += (st + i <= 9)
            p2 += (st + i > 9)
        if (rem <= 0):
            continue 
        if (flag):
            for x in range(1, 151):
                if (rem - x * p1 <= 0):
                    break 
                r = rem - x * p1 
                if (r % p2 != 0):
                    continue 
                r //= p2 
                if (pre[x][r] == -1):
                    continue    
                if (x == r):
                    continue
                ans = update(ans, pre[x][r] * 10 + st)
           #     print("have flag", ans)
        else:
            if (rem % (k + 1) != 0):
                continue 
            r = rem // (k + 1)
            if (pre[r][r] == -1):
                continue 
            ans = update(ans, pre[r][r] * 10 + st)
        #    print("no flag", ans) 
    return ans 

