def solve(A):
    if len(A) <=2 :
        return (True,0)

    if len(A) < k+2:
        if max(A) != A[0] and max(A) !=A[-1]:
            return (False,0)
        else:
            return (True,y*(len(A)-2))
    else:
        if y*k < x :
            if max(A) == A[0] or max(A) == A[-1]:
                return (True,(len(A)-2)*y)
            else:
                d=len(A)-2
                return (True,x + (d-k)*y)
        else:
            d=len(A)-2
            return (True,(d//k)*x + (d-((d//k)*k))*y)

