class Solution(object):
    def solve(self,array):
        """
        :type arr: List[int]
        :type start: int
        :rtype: bool
        """
        from collections import defaultdict,deque
        D=defaultdict(list)
        self.t_max=float('inf')
        for i in range(0,len(array)):
            if array[i]+i<len(array):
                D[array[i]+i].append(i)
            if i-array[i]>=0:
                D[i-array[i]].append(i)

        close=[self.t_max]*len(array)

        Q=deque()
        for target in D:
            for source in D[target]:
                if (array[target]+array[source])%2==1:
                    close[source]=1
                    Q.append((source,2))

        while(Q):
            #print Q
            target,step=Q.popleft()
            #print "target,step:",target,step
            for source in D[target]:
                if close[source]<=step:
                    continue

                if (array[target]+array[source])%2==1:
                    close[source]=1
                    continue
                else:
                    close[source]=min(close[source],step)
                    Q.append((source,step+1))

        for i in range(0,len(close)):
            if close[i]==self.t_max:
                close[i]=-1
        return close


