import math
import bisect
dict = {}
#print dir(bisect)
List = []
def binary_search(l,r,a):
    mid = (l+r)/2
    if(l==r):
        return mid+1
    if r-l == 1 and List[r]<=a:
        return r+1
    if r-l == 1 and List[r]>a:
        return l+1
    if List[mid]==a:
        return mid+1
    if List[mid]>a:
        return binary_search(l,mid-1,a)
    if List[mid]<a:
        return binary_search(mid,r,a)
def popcount1(a,b):
    if(dict.has_key(a) > 0):
        k1 = dict[a]
    elif a <= 0:
        k1 = 0
    else:
        k1 = bisect.bisect_right(List,a,0,len(List))
        dict[a] = k1

    if(dict.has_key(b) > 0):
        k2 = dict[b]
    elif b <= 0:
        k2 = 0
    else:
        k2 = bisect.bisect_right(List,b,0,len(List))
        dict[b] = k2
    if(k1 == k2 and  k1 == 0):
            return 0
    sum = List[k1-1]
    #print k1,k2
    if(k1 == k2):
        return sum+(popcount1((a-sum),(b-sum)))
    elif(k1!=k2 and b == List[k2]-1):
        return b
    else:
        return List[k2-1]-1

