def solve():
    if h == c:
        return 1
    if (h + c) // 2 >= t:
        print(2)
        return
    ans = bs(1, 10 ** 6)
    a1 = getdif(ans)
    a2 = getdif(ans - 1)
    if abs(t - a1) < abs(t - a2):
        print(2 * ans - 1)
    else:
        ans -= 1
        print(2 * ans - 1)
    return


def bs(l, r):
    while l < r:
        m = (l + r) // 2
        if check(m):
            r = m
        else:
            l = m + 1
    return r


def check(hh):
    temp = getdif(hh)
    # print(hh, ": ", temp)
    if temp < t:
        return 1
    else:
        return 0


def getdif(hh):
    return Decimal(hh * h + (hh-1) * c) / Decimal(2*hh-1)

