def solve(r, g, b, dp):
  for x in range(len(r) - 1, -1, -1):
    for y in range(len(g) - 1, -1, -1):
      for z in range(len(b) - 1, -1, -1):
        dp[x][y][z] = max(
          dp[x + 1][y + 1][z] + r[x] * g[y],
          dp[x][y + 1][z + 1] + g[y] * b[z],
          dp[x + 1][y][z + 1] + r[x] * b[z]
        )
  return dp[0][0][0]

