import sys
import heapq


def read_line():
    return next(sys.stdin).strip()


def read_ints():
    return map(int, read_line().split())


def case1():
    s = sum(A[K - 1] - v for v in A[:K])
    yield s * C

    for i in xrange(K, N):
        s += (K - 1) * A[i] - K * A[i - 1] + A[i - K]
        yield s * C


def case2():
    def round(x):
        return x + (r - x) % 5

    def val(v):
        return round(v) * B - (round(v) - v) * C * 5

    for r in xrange(5):
        heap = map(val, A[:K])
        heapq.heapify(heap)

        s = sum(heap)
        yield (round(A[K - 1]) * K * B - s) // 5

        for v in A[K:]:
            s += val(v) - heapq.heappushpop(heap, val(v))
            yield (round(v) * K * B - s) // 5


N, K, B, C = read_ints()
A = sorted(read_ints())
case = case1 if B >= 5 * C else case2
print min(case())

