import random

class interactor:
    def __init__(self, n):
        def correct(a, b, c, d, n):
            arr = [[0 for i in range(n + 1)] for j in range(n + 1)]
            for i in range(a[0], a[1] + 1):
                for j in range(b[0], b[1] + 1):
                    arr[i][j] += 1
            for i in range(c[0], c[1] + 1):
                for j in range(d[0], d[1] + 1):
                    arr[i][j] += 1
            for i in range(1, n + 1):
                for j in range(1, n + 1):
                    if arr[i][j] > 1:
                        return False
            return True

        def pair(n):
            x = random.randint(1, n)
            y = random.randint(1, n)
            if x > y:
                y, x = x, y
            return x, y
        self.arr = [2, 1, 5, 5, 1, 1, 1, 4]
        return
        a, b, c, d = (None for i in range(4))
        while True:
            a, b, c, d = (pair(n) for i in range(4))
            if correct(a, b, c, d, n):
                break
        self.arr = [a[0], b[0], a[1], b[1], c[0], d[0], c[1], d[1]]
        print(self.arr)

    def request(self, x1, y1, x2, y2):
        def inside(l, r, L, R):
            return l <= L and R <= r
        def ins_rect(x1, y1, x2, y2, X1, Y1, X2, Y2):
            return inside(X1, X2, x1, x2) and (
                   inside(Y1, Y2, y1, y2)
                )
        ans = 0
        if ins_rect(self.arr[0], self.arr[1], self.arr[2], self.arr[3],x1, y1, x2, y2):
            ans += 1
        if ins_rect(self.arr[4], self.arr[5], self.arr[6], self.arr[7],x1, y1, x2, y2):
            ans += 1
        return ans


    def check(self, x11, y11, x12, y12, x21, y21, x22, y22):
        def eq_arr(a, b):
            n = len(a)
            for i in range(n):
                if a[i] != b[i]:
                    return False
            return True
        a1 = [x11, y11, x12, y12, x21, y21, x22, y22]
        a2 = [x21, y21, x22, y22, x11, y11, x12, y12]
        return eq_arr(self.arr, a1) or eq_arr(self.arr, a2)

