import fileinput

def levels(n, e):
	l = [0 for _ in range(n)]
	q = [(0, -1, 0)]
	while q:
		v, u, d = q.pop()
		l[v] = d

		for w in e[v]:
			if w != u: q.append((w, v, d+1))
	return l

def solve(n, e, x, g):
	l = levels(n, e)

	f = [0, 0]
	q = [(0, -1)]
	z = []
	while q:
		v, u = q.pop()

		if v == -1:
			f = u
			continue
		q.append((-1, f[:]))

		d = l[v]%2
		if (x[v]+f[d])%2 != g[v]:
			f[d] = (f[d]+1)%2
			z.append(v)

		for w in e[v]:
			if w != u: q.append((w, v))

	print(len(z))
	for v in z: print(v+1)

