import sys
from array import array  # noqa: F401
import typing as Tp  # noqa: F401


def input():
    return sys.stdin.buffer.readline().decode('utf-8')


T = Tp.TypeVar('T')


class FenwickSum(Tp.Generic[T]):
    __slots__ = ['nodes', 'size', 'unit']

    def __init__(self, size: int, default: T, unit: T):
        self.nodes = [default] * (size + 1)
        self.size = size + 1
        self.unit = unit

    def add(self, index: int, value: T):
        while index < self.size:
            self.nodes[index] += value
            index += index & -index

    def sum(self, right: int) -> T:
        result = self.unit

        while right:
            result += self.nodes[right]
            right -= right & -right

        return result


def main():
    n = int(input())
    vertical, horizontal = [], []
    for x1, y1, x2, y2 in (map(lambda x: int(x) + 5002, input().split()) for _ in range(n)):
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1
        if x1 == x2:
            vertical.append((x1, y1, x2, y2))
        else:
            horizontal.append((x1, y1, x2, y2))

    vertical.sort()
    horizontal.sort(key=lambda p: -p[2])
    ans = 0
    bit = FenwickSum[int](10010, 0, 0)

    for i, (x1, y1, x2, y2) in enumerate(vertical):
        stack = []

        for x3, y3, x4, y4 in horizontal:
            if y1 <= y3 <= y2 and x3 <= x1 <= x4:
                stack.append((x4, y3))
                bit.add(y3, 1)
        for x3, y3, x4, y4 in vertical[i + 1:]:
            while stack and stack[-1][0] < x3:
                bit.add(stack.pop()[1], -1)
            cnt = bit.sum(y4) - bit.sum(y3 - 1)
            ans += (cnt * (cnt - 1)) >> 1
        for _, y in stack:
            bit.add(y, -1)

    print(ans)


