def fix(grid,x,y, rev, moves):
    want = grid[x][y][1]
    while x < want:
        if grid[x+1][y]:
            fix(grid,x+1,y,rev, moves)
        st = (x,y,x+1,y)
        if rev:
            st = (st[2],st[3],st[0],st[1])
        moves.append(' '.join(map(str,st)))
        grid[x+1][y], grid[x][y] = grid[x][y], grid[x+1][y]
        x+=1
    while x > want:
        if grid[x-1][y]:
            fix(grid,x-1,y,rev, moves)
        st = (x,y,x-1,y)
        if rev:
            st = (st[2],st[3],st[0],st[1])
        moves.append(' '.join(map(str,st)))
        grid[x-1][y], grid[x][y] = grid[x][y], grid[x-1][y]
        x-=1

def solve(cubes, rev):
    global n,m
    cubes=[[cubes[i][0],cubes[i][1],i+1] for i in xrange(m)]
    cubes.sort()
    moves = []
    grid=[[0 for i in xrange(n+1)]for j in xrange(n+1)]
    for i,(x,y,z) in enumerate(cubes):
        grid[x][y] = (z,i+1)
    for i in xrange(n+1):
        for j in xrange(n+1):
            if grid[i][j]:
                fix(grid,i,j,rev, moves)
    cubes = []
    for i in xrange(n+1):
        for j in xrange(n+1):
            if grid[i][j]:
                cubes.append([i,j,grid[i][j][0]])

    for i in xrange(m):
        want = cubes[i][-1]
        while cubes[i][1] < want:
            st = (cubes[i][0], cubes[i][1], cubes[i][0], cubes[i][1] + 1)
            if rev:
                st = (st[2],st[3],st[0],st[1])
            moves.append(' '.join(map(str,st)))
            cubes[i][1] += 1
        while cubes[i][1] > want:
            st = (cubes[i][0], cubes[i][1], cubes[i][0], cubes[i][1] - 1)
            if rev:
                st = (st[2],st[3],st[0],st[1])
            moves.append(' '.join(map(str,st)))
            cubes[i][1] -= 1
    for i in xrange(m):
        want = cubes[i][-1]
        while cubes[i][0] < want:
            st = (cubes[i][0], cubes[i][1], cubes[i][0] + 1, cubes[i][1])
            if rev:
                st = (st[2],st[3],st[0],st[1])
            moves.append(' '.join(map(str,st)))
            cubes[i][0] += 1
        while cubes[i][0] > want:
            st = (cubes[i][0], cubes[i][1], cubes[i][0] - 1, cubes[i][1])
            if rev:
                st = (st[2],st[3],st[0],st[1])
            moves.append(' '.join(map(str,st)))
            cubes[i][0] -= 1
    return moves

