def readGraph(n, m):
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u,v = map(int, inputi().split())
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)
    return adj

def solve():
    n = int(inputi())
    adj = readGraph(n, n)
    parent = [None] * n
    depth = [0]*n
    q = deque()
    q.append(0)
    loop = deque()
    while not loop:
        c = q.popleft()
        for a in adj[c]:
            if a != parent[c]:
                if parent[a] != None:
                    loop.append(a)
                    loop.append(c)
                    break
                else:
                    parent[a] = c
                    depth[a] = depth[c]+1
                    q.append(a)
    while loop[0] != loop[-1]:
        if depth[loop[0]] > depth[loop[-1]]:
            loop.appendleft(parent[loop[0]])
        else:
            loop.append(parent[loop[-1]])
    loop = list(loop)[:-1]
    ls = len(loop)
    lc = []
    for i in range(ls):
        l = loop[i]
        q = deque()
        q.append(l)
        count = 0
        visited = {loop[(i-1)%ls], l, loop[(i+1)%ls]}
        while q:
            for a in adj[q.popleft()]:
                if a not in visited:
                    count += 1
                    visited.add(a)
                    q.append(a)
        lc.append(count)
    treecount = (n*(n-1))//2
    loopcount = (ls*(ls-1))//2
    lt = (ls-1)*(n - ls)
    tt = sum(c * (n - c - ls) for c in lc)//2
    res = treecount+loopcount+lt+tt
    print(res)






def main():
    t = int(inputi())
    for _ in range(t):
        solve()


if __name__ == "__main__":
    main()

