def memo(func):  
    cache={}  
    def wrap(*args):  
        if args not in cache:  
            cache[args]=func(*args)  
        return cache[args]  
    return wrap

@memo
def comb (n,k):
    if k>n: return 0    
    if k==0: return 1
    if n==k: return 1
    return comb(n-1,k-1) + comb(n-1,k)
def getclam(K, left = 3):
    if K==0: return 1
    if left ==0: return 1
    s = str(K)
    l = len(s)

    r = 0
    x = int(s[0])
    if l>1:
        for i in range(left+1):
            r += comb(l-1,i) * 9 ** i
        if x>0:
            for i in range(left):
                r += comb(l-1,i) * 9 ** i * (x-1)
        s1 = s[1:]
        y = 0
        if s1:
            y = int(s1)
        if x!=0:
            left-=1
        r+= getclam( y, left)
        return r
    else:
        return x+1
