	one = []
	two = []
	for i in range(0,len(digi)):
		if int(digi[i]) % 3 == 1:
			one.insert(0,i)
		elif int(digi[i]) % 3 == 2:
			two.insert(0,i)
	modResult = []
	modResult.append(one)
	modResult.append(two)
	return modResult

