#!/usr/bin/env python3

from __future__ import division, print_function

def least_significant_bit(i):
    return ((i) & -(i))

class FenwickTree():
    def __init__(self, n):
        # 1-indexed
        self.n = n + 1 
        self.data = [0,] * self.n

    def add(self, index, value):
        # 1-indexed
        i = index + 1
        while i < self.n:
            self.data[i] += value
            i += least_significant_bit(i)

    def prefix_sum(self, index):
        # 1-indexed
        i = index + 1
        result = 0
        while i > 0:
            result += self.data[i]
            i -= least_significant_bit(i)
        return result

def solver(ifs):
    n = int(ifs.readline().strip())
    left = [0,] * n
    right = [0,] * n
    for i in range(n):
        left[i], right[i] = map(int, ifs.readline().split())
    order = list(range(n))
    order.sort(key=lambda x: left[x])
    for i, k in enumerate(order):
        left[k] = i
    order.sort(key=lambda x:right[x])
    res = [0, ] * n
    ft = FenwickTree(n)
    for i, k in enumerate(order):
        a = left[k]
        res[k] = i - ft.prefix_sum(a-1)
        ft.add(a, 1)
    print('\n'.join(str(x) for x in res))


def main():
    import sys
    if sys.version_info.major == 3:
        from io import StringIO as StreamIO
    else:
         from io import BytesIO as StreamIO

    with StreamIO(sys.stdin.read()) as ifs, StreamIO() as ofs:
        _stdout = sys.stdout
        sys.stdout = ofs
        solver(ifs)
        sys.stdout = _stdout
        sys.stdout.write(ofs.getvalue())
    return 0

if __name__ == '__main__':
    main()

