def parse(c, n):


    l = [-1] * n

    for x in c:
        se = set(x)

        for i in range(len(x) - 1):

            for j in range(i + 1, len(x)):
                k = x[j] - x[i]

                if k > 20:
                    break

                if x[i] + k + k >= n:
                    break

                if x[i] + k + k in se:
                    l[x[i] + k + k] = x[i]
                    break

    res = 0


    prex = -1
    # print(l)

    for i in range(n):
        if l[i] <= prex:
            continue
        res = res + (l[i] - prex) * (n - i);
        # print(prex + 1, l[i], i + 1, n)
        prex = l[i]
    return res


