def solve(arr):
	n = len(arr)
	s = set()
	for i in range(n-1, -1, -1):
		if arr[i] not in s:
			s.add(arr[i])
		else:
			break
	ans = n-len(s)
	s.clear()
	for i in range(n):
		if arr[i] not in s:
			s.add(arr[i])
			s1 = set(s)
			for i in range(n-1, -1, -1):
				if arr[i] not in s1:
					s1.add(arr[i])
				else:
					break
			ans = min(ans, n-len(s1))
		else:
			break
	return ans

def main():
	n = int(input())
	arr = list(map(int, input().split()))
	print(solve(arr))


