def BFS(sr, sc, fr, fc):
  q = [0] * (MAX * MAX)
  left = right = 0
  q[0] = (sr, sc)
  while left <= right:
    ur, uc = q[left]
    left += 1
    for i in range(4):
      vr = ur + dr[i]
      vc = uc + dc[i]
      if isValid(vr, vc):
        if maze[vr][vc] == '.':
          maze[vr][vc] = 'X'
          right += 1
          q[right] = (vr,vc)
        else:
          if(vr == fr) and (vc==fc):
            return True
  return False

