        i = 0
        while i < n - 1:
            if l1[i] == "R" and l1[i+1] == "L":
                temp.append(i + 1)
                l2.append("L")
                l2.append("R")
                i += 2
            else:
                l2.append(l1[i])
                i += 1
        while i < n:
            l2.append(l1[i])
            i += 1
        l1 = l2
        if len(temp) == 0:
            break
        stages.append(temp)
    total_moves = 0
