        total_moves += len(x)
    if total_moves < k or k < min_moves:
        print(-1)
    else:
        x = len(stages)
        if x == k:
            for i in range(x):
                print(len(stages[i]), end = " ")
                print(*stages[i])
        else:
            flag = 0
            for i in range(len(stages)):
                for j in range(len(stages[i])):
                    print(1, stages[i][j])
                    k -= 1
