        alist = unique(alist)
        output.append(cal(alist, len(alist)))
    for x in output:
        print(x)

def unique(alist):
    unique = [alist[0]]
    for i in range(1,len(alist)):
        if alist[i] < unique[len(unique)-1]:
            unique.append(alist[i])
    return unique

