def is_star(grid, x, y):
    left , right , uper , lower= (-1,-1,-1,-1)

    for i in range(y,m,1):
        if (x,i) in star_mem:
            left += star_mem[(x,i)][0]+1
            break
        if grid[x][i] == '*':
            left += 1
        else :
