from sys import stdin

def r(): return stdin.readline().strip()
def r_t(tp): return map(tp, r().strip().split())
def r_a(tp): return list(r_t(tp))

def solve(n,k,z,A):
    ans = float("-inf")
    for t in range(0,z+1):
        ac, x = 0, -1
        #if k-2*t < 0: continue
        for i in range((k - 2*t) + 1):
            ac+=A[i]
            if i < n-1: x=max(x,A[i]+A[i+1])
        ac+=(x*t)
        ans = max(ans, ac)

    #print(">>",sum(A[:k]))
    return ans

