import sys
n, L, minID = None, None, None
s = []

def fill(id, c):
    global n, L, s, minID
    L -= (s[id] == 'L')
    s = s[0:id] + c + s[ id +1:]
    minID = min(minID, id)

def query(cmd, str):
    global n, L, s, minID
    print(cmd, ''.join(str))
    print(cmd, ''.join(str), file=sys.stderr)
    sys.stdout.flush()
    if (cmd == '?'):
        result = list(map(int, input().split()))
        assert(result[0] != -1)
        for z in result[1:]:
            z -= 1
            for i in range(len(str)):
                assert(s[z+i] == 'L' or s[z+i] == str[ i ])
                fill(z+i, str[i])
    elif (cmd == '!'):
        correct = int(input())
        assert(correct == 1)

