                if a[l] < a[r]:
                    t = a[l]
                    o.append('L')
                    l += 1
                elif a[r] < a[l]:
                    t = a[r]
                    o.append('R')
                    r -= 1
                else:
                    dl, dr = 0, 0
                    for i in range(l, r):
                        if a[i] < a[i + 1]:
                            dl += 1
                        else:
                            break

                    for i in range(r, l, -1):
                        if a[i] < a[i - 1]:
                            dr += 1
                        else:
                            break

                    if dl > dr:
                        t = a[l]
                        o.append('L')
                        l += 1
                    else:
                        t = a[r]
                        o.append('R')
                        r -= 1

            elif a[l] > t:
                t = a[l]
                o.append('L')
                l += 1
            elif a[r] > t:
                t = a[r]
                o.append('R')
                r -= 1

        # print(s)
        # print(o)
        print(len(o))
        print(''.join(o))

    except:
        break

