def dfs(node,g):
    sons = []
    for nb in g[node]:
        if not visited[nb]:
            visited[nb] = 1
            dfs(nb,g)
            sons.append(nb)

    dp[node][0] = ws[node-1]
    for s in sons:
        dp[node][0] += dp[s][k]


    ls = len(sons)
    # print node,sons,g[node]
    for i in range(ls):
        for j in range(k+1):
            d2 = max(k-1-j,0)
            maxd = j+1
            if d2+1<maxd and ls>1:
                d2 = j
            tmp = dp[sons[i]][j]
            for s in range(ls):
                if s==i:
                    continue
                tmp += dp[sons[s]][d2]
            dp[node][maxd] = max(dp[node][maxd],tmp)

    for i in range(k)[::-1]:
        dp[node][i] = max(dp[node][i],dp[node][i+1])



