def find_next(ind):
	cur,found = ind,False
	change = set()

	while not found:
		if cur > N-1 or next_ind[cur] == cur:
			found = True
		else:
			change.add(cur)
			cur = next_ind[cur]

	for i in change:
		next_ind[i] = cur

	return cur

