	cur = find_next(l)

	while cur <= r:
		if cur == x:
			if cur == r:
				break

			cur = find_next(cur+1)
		else:
			conq[cur] = x+1
			next_ind[cur] = cur+1

			if cur == r:
				break

			cur = find_next(cur+1)

