import sys

def read_address(s):
  result = 0
  base = 1
  for part in reversed(s.split('.')):
    result += int(part) * base
    base *= 256
  return result

def write_address(x):
  parts = 4 * [ None ]
  base = 256
  for i in range(4):
    parts[3 - i] = (x & 255)
    x >>= 8
  return '.'.join(map(str, parts))

n, k = map(int, raw_input().split())
addresses = [ read_address(raw_input().strip()) for i in range(n) ]
big = (1 << 32) - 1
antimask = big
for i in range(31):
  antimask >>= 1
  mask = (big ^ antimask)
  subnets = set()
  for address in addresses:
    subnets.add(address & mask)
  if len(subnets) < k:
    continue
  if len(subnets) == k:
    print(write_address(mask))
  else:
    print(-1)
  sys.exit()
