    else:
        if p1 != INF: hpush(free, p1)

        if p2 < p[i]:
            hpush(free, p2)
            hpush(sold, p[i])

            ans += (p[i] - p2)
        else:
            hpush(sold, p2)
            hpush(free, p[i])

