n, k = map(int, input().split())
p  = {}
np = {}
pair    = []
used    = {}
rev_d   = {}

def push(d, s, v):
    if s not in d:
        d[s] = []
    d[s].append(v)

def is_pal(s):
    n = len(s)
    flg=True
    for i in range(n//2):
        if s[i] != s[n-1-i]:
            flg = False
            break
    return flg        

def rev(s):
    return s[::-1]

for _ in range(n):
    s, val = input().split()
    val    = int(val)

    if is_pal(s):
        push(p, s, val)
    else:
        push(np, s, val)

        if s not in rev_d:
            rev_d[s] = rev(s)

for k, v in p.items():
    p[k] = sorted(v, reverse=True)

for k, v in np.items():
    np[k] = sorted(v, reverse=True)

for s in np:
    if s not in used and rev_d[s] in np:
        pair.append([s, rev_d[s]])
        used[s] = True
        used[rev_d[s]] = True

