            if v_arr[i] > 0:
                max_remain = max(max_remain, v_arr[i]) 

        else:
            if v_arr[i] + v_arr[i+1] >= 0:
                max_S += v_arr[i] + v_arr[i+1]

                if v_arr[i+1] < 0:
                    minus = min(minus, v_arr[i+1])
            else:
                if v_arr[i] > 0:
                    max_remain = max(max_remain, v_arr[i]) 

for [u, v] in pair:
