def f(n):
    mx = len(str(n))
    ans = 0
    for i in range(1, mx):
        for j in range(1, 10):
            if i == 1:
                ans += 1
            else:
                ans +=  (10 ** (i - 2))
    for j in range(1, 10):
        if mx == 1:
            if j <= n:
                ans += 1
            else:
                break
            continue
        if int(str(j) + '0' * (mx - 2) + str(j)) > n:
            break
        if int(str(j) + '9' * (mx - 2) + str(j)) <= n:
            ans +=  (10 ** (mx - 2))
        else:
            val = int(str(n)[1:-1]) + 1
            if str(n)[-1] < str(n)[0]:
                val -= 1
            ans += val
            break
    return ans


