def main():
    n = int(raw_input())
    aa = list(map(int, raw_input().split()))
    raw_input()
    res = []
    if n < 2:
        l, f = ("01"[aa[0] > aa[-1]], "01"[aa[0] < aa[-1]]), False
        for q in raw_input()[::2]:
            f ^= q == '1'
            res.append(l[f])
        print('\n'.join(res))
        return
    n2 = 2 ** n
    a00 = a01 = a10 = a11 = 0
    for i in xrange(0, n2, 4):
        a, b, c, d = aa[i:i + 4]
        a00 += (b < a) + (d < c)
        a01 += (c < a) + (c < b) + (d < a) + (d < b)
        a10 += (b > a) + (d > c)
        a11 += (c > a) + (c > b) + (d > a) + (d > b)
    acc0 = [a00, a01]
    acc1 = [a10, a11]
    w = 4
    while w < n2:
        a00 = a10 = 0
        for i in xrange(0, n2, w * 2):
            le = sorted(aa[i:i + w])
            ri = sorted(aa[i + w:i + w * 2])
            i = j = 0
            try:
                while True:
                    if le[i] > ri[j]:
                        j += 1
                    else:
                        a00 += j
                        i += 1
            except IndexError:
                if i < j:
                    a00 += j * (w - i)
            i = j = 0
            try:
                while True:
                    if ri[i] > le[j]:
                        j += 1
                    else:
                        a10 += j
                        i += 1
            except IndexError:
                if i < j:
                    a10 += j * (w - i)
        acc0.append(a00)
        acc1.append(a10)
        w *= 2
    for q in map(int, raw_input().split()):
        while q:
            q -= 1
            acc0[q], acc1[q] = acc1[q], acc0[q]
        res.append(sum(acc0))
    print('\n'.join(map(str, res)))


