from collections import defaultdict, Counter

class Solution:
    def __init__(self):
        pass

    def solve_and_print(self):
        d, c = defaultdict(int), []
        for _ in range(int(input())):
            x, y = [int(x) for x in input().split()]
            c += [x, y]
            d[x] += y
