from collections import deque
def main():
    n, m, k, q = map(int, stdin.readline().split())
    dat = map(int, stdin.read().split(), repeat(10, 3 * q))
    inf = 10 ** 9 + 1
    a = [[inf] * m for i in xrange(n)]
    for i in xrange(q):
        x, y, z = dat[i*3:i*3+3]
        a[x-1][y-1] = z
    r = [[0] * m for i in xrange(n)]
    for i in xrange(n):
        st = deque()
        for j in xrange(k):
            t = (a[i][j], j)
            while st and st[-1] <= t:
                st.pop()
            st.append(t)
        r[i][k-1] = st[0][0]
        for j in xrange(k, m):
            t = (a[i][j], j)
            while st and j - st[0][1] >= k:
                st.popleft()
            while st and st[-1] <= t:
                st.pop()
            st.append(t)
            r[i][j] = st[0][0]
    ans = inf
    for i in xrange(k-1, m):
        st = deque()
        for j in xrange(k):
            t = (r[j][i], j)
            while st and st[-1] <= t:
                st.pop()
            st.append(t)
        if ans > st[0][0]:
            ans = st[0][0]
        for j in xrange(k, n):
            t = (r[j][i], j)
            while st and j - st[0][1] >= k:
                st.popleft()
            while st and st[-1] <= t:
                st.pop()
            st.append(t)
            if ans > st[0][0]:
                ans = st[0][0]
    if ans == inf:
        ans = -1
    print ans
