from math import ceil
def solve(field,size,answer):
    left = 0
    star_pos = -1
    rstar_pos = -1
    p_pos = -1
    distance = 0
    cost = 0
    for i in range(size):
        #print(p_pos,star_pos)
        if field[i] == "*":
            if star_pos != -1:
                if p_pos != -1:
                    if star_pos < p_pos and i > p_pos: #*...P.*.* star on both side of P
                        if min(2*(p_pos-star_pos)+(i-p_pos),2*(i-p_pos)+\
                               (p_pos-star_pos)) > answer:
                            star_pos = i
                            p_pos = -1
                            continue
                    elif i-p_pos > answer: #..P..*P when star on the right of P
                        star_pos = i
                        p_pos = -1
                        continue
            else:
                if p_pos != -1:
                    if i - p_pos > answer:
                        p_pos = -1
                star_pos = i

        if field[i] == "P":
            if p_pos != -1:
                distance = 0
                star_pos = -1
            if star_pos != -1:
                #print("star_pos:",star_pos,"current pos",i)
                if i - star_pos > answer:
                    return -1

            p_pos = i

    if p_pos == -1:
        return -1
    return 1




