from sys import stdin
import re


def get(s):
    throw, error = '', ''
    be, en = s.find('(') + 1, s.find(')') - 1

    while s[be] != ',':
        throw += s[be]
        be += 1

    while s[en] != ',':
        if s[en] != '\"':
            error += s[en]
        en -= 1

    return throw.strip(), error[::-1].strip()


def get_throw(s):
    be, throw = s.find('(') + 1, ''

    while s[be] != ')':
        throw += s[be]
        be += 1

    return throw.strip()


