import math
from collections import defaultdict

def main():
    MOD7 = 1000000007
    t = int(stdin.readline())
    pw = [0] * 21
    for w in range(20,-1,-1):
        pw[w] = int(math.pow(2,w))
    for ks in range(t):
        n,p = list(map(int, stdin.readline().split()))
        arr = list(map(int, stdin.readline().split()))
        if p == 1:
            if n % 2 ==0:
                stdout.write("0\n")
            else:
                stdout.write("1\n")
            continue
        arr.sort(reverse=True)
        left = -1
        i = 0
        val = [0] * 21
        tmp = p
        val[0] = p
        slot = defaultdict(int) 
        for x in range(1,21):
            tmp = (tmp * tmp) % MOD7
            val[x] = tmp
        while i < n:
            x = arr[i]
            if left == -1:
                left = x
            else:
                slot[x] += 1
                tmp = x
                if x == left:
                    left = -1
                    slot.pop(x)
                else:
                    while slot[tmp] % p == 0:
                        slot[tmp+1] += 1
                        slot.pop(tmp)
                        tmp += 1
                    if tmp == left:
                        left = -1
                        slot.pop(tmp)
            i+=1
        if left == -1:
             stdout.write("0\n")
             continue
        res = 1
        for w in range(20,-1,-1):
            pww = pw[w]
            if pww <= left:
                left -= pww
                res = (res * val[w]) % MOD7
            if left == 0:
                break
        for x,c in slot.items():
            tp = 1
            for w in range(20,-1,-1):
                pww = pw[w]
                if pww <= x:
                    x -= pww
                    tp = (tp * val[w]) % MOD7
                if x == 0:
                    break
            res = (res - tp * c) % MOD7
        stdout.write(str(res)+"\n")


