	for j in range(i,len(s)):
		if(s[i]!=s[j]):
			if(s[i]=="A"):
				count+=a
			else:
				count+=b
			i=j
	if(i<len(s)-1):
		if(s[i]=="A"):
			count+=a
		else:
			count+=b
	return count


