def Gauss(n,m):
    for i in range(n-1):
        Max=i
        for j in range(i,n):
            if a[j][i]>a[Max][i]:
                Max=j
        for j in range(m):
            a[i][j],a[Max][j]=a[Max][j],a[i][j]
        if a[i][i]==0:
            continue
        for j in range(i+1,m):
            a[i][j]/=a[i][i]
        a[i][i]=1
        for j in range(i+1,n):
            tmp=a[j][i]/a[i][i]
            for k in range(i,m):
                a[j][k]-=tmp*a[i][k]
