def getmin(first, second):
    if second - first + 1 >= n:
        return mn
    else:
        second = second % n + n * (not(second % n))
        first = first % n + n * (not(first % n))

        if second < first:
            return min(getmin(1, second), getmin(first, n))
        else:
            length = second - first + 1
            pw = 0

            while 2 ** pw <= length:
                pw += 1

            pw -= 1

            return min(sparse[pw][first], sparse[pw][second - 2 ** pw + 1])


