def find_d(A):
    n = max(A) + 1
    A = [None] + A
    ind = [[] for _ in range(n)]
    for i in range(len(A)):
        if not A[i]:
            continue
        if len(ind[A[i]]) == 2:
            ind[A[i]][1] = i
        else:
            ind[A[i]].append(i)
    min_ind = len(A)
    d = 0
    for l in ind:
        if len(l) == 1:
            if l[0] < min_ind:
                min_ind = l[0]
            else:
                if d < l[0] - min_ind:
                    d = l[0] - min_ind
                    r = (d, min_ind)
        elif len(l) == 2:
            if d < l[1] - min_ind:
                d = l[1] - min_ind
                r = (d, min_ind)
            if l[0] < min_ind:
                min_ind = l[0]
        else:
            continue
    return d


