from __future__ import division, print_function

from collections import deque
class Node:
    def __init__(self, c, nxt, fail, o):
        self.c = c
        self.nxt = nxt
        self.fail = fail
        self.o = o

root = Node('', {}, Node, 0)
root.fail = root

def new_node(par, c):
    node = Node(c, {}, root, 0)
    par.nxt[c] = node
    return node

def go(n, c):
    while True:
        try:
            return n.nxt[c]
        except KeyError:
            if n != root:
                n = n.fail
            else:
                return root

def build(ps):
    for i, p in enumerate(ps):
        n = root
        for c in p:
            try:
                n = n.nxt[c]
            except KeyError:
                n = new_node(n, c)
        n.o += 1

    q = deque([root])
    while q:
        n = q.popleft()
        for c, cn in n.nxt.iteritems():
            q.append(cn)
            if n == root:
                cn.fail = root
            else:
                cn.fail = go(n.fail, c)
            cn.o += cn.fail.o

def query(s, ar):
    n = root
    for i, c in enumerate(s):
        n = go(n, c)
        ar[i] += n.o

def main():
    s = input()
    ps = [input() for _ in range(int(input()))]

    build(ps)
    far = array_of(int, len(s))
    query(s, far)

    root.nxt = {}
    root.o = 0

    rps = [list(reversed(ss)) for ss in ps]
    rs = list(reversed(s))

    build(rps)
    bar = array_of(int, len(rs))
    query(rs, bar)

    ans = 0
    for i in range(len(s)-1):
        ans += bar[i] * far[len(s)-2-i]
    print(ans)

