        else:
            x = min_st[i+1]
            while x != -1 and h[i] < h[x]:
                x = min_st[x]
            min_st[i] = x
        if h[i]<=h[i+1]:
            max_st[i] = i+1
        else:
            x = max_st[i+1]
            while x != -1 and h[i] > h[x]:
                x = max_st[x]
            max_st[i] = x
    max_st1 = [-1]*n
    min_st1 = [-1]*n
    for i in range(1,n):
        if h[i]>=h[i-1]:
            min_st1[i] = i-1
        else:
            x = min_st1[i-1]
            while x != -1 and h[i] < h[x]:
                x = min_st1[x]
            min_st1[i] = x
        if h[i]<=h[i-1]:
            max_st1[i] = i-1
        else:
            x = max_st1[i-1]
            while x != -1 and h[i] > h[x]:
                x = max_st1[x]
            max_st1[i] = x
