from collections import defaultdict

n, m = list(map(int, input().split()))

W = list(map(int, input().split()))

favorites = []
for i in range(m):
    x, y = list(map(int, input().split()))
    favorites.append([x - 1, y - 1])

friends = defaultdict(list)
for i, (x, y) in enumerate(favorites):
    friends[x].append(i)
    friends[y].append(i)

S = [len(friends[i]) for i in range(n)]
food_items = set()

for i in range(len(S)):
    if S[i] <= W[i]:
        food_items.add(i)

resolved_food_items = set()
resolved_friends = set()
order = []

while food_items:
    food = food_items.pop()
    resolved_food_items.add(food)

    for friend in friends[food]:
        if friend not in resolved_friends:
            order.append(friend)
            resolved_friends.add(friend)
        for i in favorites[friend]:
            S[i] -= 1
            if i not in resolved_food_items and S[i] <= W[i]:
                food_items.add(i)


if len(order) == m:
    print('ALIVE')
    print(' '.join([str(i + 1) for i in order[::-1]]))
else:
    print('DEAD')


