def longest_path():
    try:
        d = [-1 for _ in range(n)]
        d[0] = 0; q = [0]
        for i in range(n):
            f = q[i]
            for t in g[f]:
                if d[t] == -1:
                    q.append(t)
                    d[t] = d[f] + 1
        u = q[-1]
        d = [-1 for _ in range(n)]
        p = [-1 for _ in range(n)]
        d[u] = 0; q = [u]
        for i in range(n):
            f = q[i]
            for t in g[f]:
                if d[t] == -1:
                    q.append(t)
                    d[t] = d[f] + 1
                    p[t] = f
        v = q[-1]
        ld = d[v]
        w = v
        if ld & 1:
            return u, v, None
        while d[w] != (ld >> 1):
            w = p[w]
        return u, v, w
    except:
        print(f'Error raised in longest_path()')


def top(u):
    try:
        if u is None:
            return False
        dist = [-1 for _ in range(n)]
        deg = [-1 for _ in range(n)]
        dist[u] = 0; q = [u]
        for i in range(n):
            f = q[i]
            if deg[dist[f]] == -1:
                deg[dist[f]] = len(g[f])
            elif len(g[f]) != deg[dist[f]]:
                return False
            for t in g[f]:
                if dist[t] == -1:
                    q.append(t)
                    dist[t] = dist[f] + 1
        return True
    except:
        print(f'Error raised in top({u})')


def semitop(w):
    try:
        if w is None:
            return False, None
        d = [-1 for _ in range(n)]
        d[w] = 0; q = [w]; i = 0
        while i < len(q):
            f = q[i]
            for t in g[f]:
                if d[t] == -1:
                    if len(g[t]) != 2:
                        d[t] = 100_500
                        if top(t):
                            return True, t
                    else:
                        d[t] = d[f] + 1
                        q.append(t)
            i += 1
        return False, None
    except:
        print(f'Error raised in semitop({w})')


