from collections import *

def bfs(sta):
    dist = [-1]*n
    dist[sta] = 0
    par = [-1]*n
    q = deque([sta])

    while q:
        v = q.popleft()

        for nv in G[v]:
            if dist[nv]==-1:
                dist[nv] = dist[v]+1
                par[nv] = v
                q.append(nv)

    return dist, par

def mbfs():
    dist = [-1]*n
    l = [b]

    while par[l[-1]]!=-1:
        l.append(par[l[-1]])

    q = deque([])

    for li in l:
        dist[li] = 0
        q.append(li)

    while q:
        v = q.popleft()

        for nv in G[v]:
            if dist[nv]==-1:
                dist[nv] = dist[v]+1
                q.append(nv)

    return dist

