def dfs():
    visited = [False for i in range(n)]
    colour = [0 for i in range(n)]
    ans = 0
    for v in range(n):
        if visited[v]: continue
        stack = [(v, 0)]
        part = [0, 0]
        while stack:
            node, c = stack.pop()
            if not visited[node]:
                part[c] += 1
                visited[node] = True
                colour[node] = c
                stack.extend((u,c^1) for u in E[node])
            elif c != colour[node]:
                return (0, 1)
        ans += (part[0]*(part[0] - 1) + part[1]*(part[1] - 1)) // 2
    return (1, ans)

