from itertools import permutations


def check(a, n):
    arr = [[0 for j in range(n)] for i in range(n)]
    p = 0
    for i in range(n):
        for j in range(n):
            arr[i][j] = a[p]
            p += 1
    s = sum(arr[0])
    for i in range(1, n):
        if s != sum(arr[i]):
            return False

    for i in range(n):
        s1 = 0
        for j in range(n):
            s1 += arr[j][i]
        if s1 != s:
            return False
    s2 = 0
    for i in range(n):
        s2 += arr[i][i]
    if s2 != s:
        return False

    s2 = 0
    for i in range(n):
        s2 += arr[i][n-i-1]
    if s2 != s:
        return False

    return True


