def maxheight(start, end):
    start_day, start_height = start
    end_day, end_height = end

    ddays = end_day - start_day
    dheight = end_height - start_height

    xdays = ddays - abs(dheight)

    if xdays < 0:
        return -1
    else:
        return xdays // 2 + max(start_height, end_height)

