def check(coor1, coor2):
    dx = coor1[0] - coor2[0]
    dy = coor1[1] - coor2[1]
    if dx % 2 != 0 or dy % 2 != 0 :
        return False
    if ((dx/2)-(dy/2) )% 2==0 and dx/2%2 == 0:
        return True

    return False

