q = int(stdin.readline())
for _ in xrange(q):
    l, r = map(int, stdin.readline().split())
    elements = r - l + 1
    if elements % 2 == 0:
        res = elements // 2
        if l % 2 == 0:
            write(-res)
        else:
            write(res)
    else:
        res = elements // 2
        if l % 2 == 0:
            write(-res + r)
        else:
            write(res - r)

