from __future__ import division
from sys import stdin, stdout
from math import sqrt, ceil

pow(1, 2, 3)


def write(x):
    stdout.write(str(x) + "\n")


def mmul(a, b, p):
    assert len(a[0]) == len(b)

    n = len(a)
    m = len(a[0])
    k = len(b[0])

    res = [[0] * k for _ in xrange(n)]
    for r in xrange(n):
        for c in xrange(k):
            sum = 0
            for i in xrange(m):
                sum = (sum + a[r][i] * b[i][c]) % p
            res[r][c] = sum
    return res


def mpow(a, x, p):
    if x == 1:
        return a
    if x % 2 == 1:
        return mmul(mpow(a, x - 1, p), a, p)
    else:
        res = mpow(a, x // 2, p)
        return mmul(res, res, p)


def xgcd(b, a):
    x0, x1, y0, y1 = 1, 0, 0, 1
    while a != 0:
        q, b, a = b // a, a, b % a
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return b, x0, y0


def solve(a, c, m):
    res, x0, y0 = xgcd(a, m)
    if c % res != 0:
        return -1
    a //= res
    c //= res
    m //= res
    res, x0, y0 = xgcd(a, m)
    assert res == 1
    return (x0 * c) % m


def shanks(alpha, beta, p):
    t = int(ceil(sqrt(p)))
    small = {beta: 0}
    b = beta
    for i in range(1, t + 1):
        b = (b * alpha) % p
        small[b] = i
    for i in range(0, p, t):
        temp = pow(alpha, i, p)
        if temp in small:
            return (i - small[temp]) % (p - 1)
    assert False


