from itertools import combinations

def calculate(s, dif):
	x = int(s, 2)
	for j in combinations(range(len(s)), dif):
		y = x
		for k in j:
			y ^= (2**k)
		yield y

def calculate2(s, dif, arr):
	y = int(s, 2)
	for x in arr:
	    if(bin(y ^ x).count('1') == dif):
	        yield x


