	s = s.replace('W', '0')
	ans1 = solve(n, list(s))
	s = list(s)
	for i in range(n):
		if s[i] == '1':
			s[i] = '0'
		else:
			s[i] = '1'
	ans2 = solve(n, list(s))
	if ans1 != [-1] and len(ans1) <= 3*n:
		print(len(ans1))
		print(*ans1)
	elif ans2 != [-1] and len(ans2) <= 3*n:
		print(len(ans2))
