def isFallen(n, matrix):
	fallen = [1 for i in range(n)]
	for i in range(n):
		for j in range(n):
			if i != j:
				if matrix[i][j] == 3:
					fallen[i] = 0
				if matrix[i][j] == 1:
					fallen[i] = 0
	survived = []
	for i in range(len(fallen)):
		if fallen[i] == 1:
			survived.append(i)
	return (survived)

