def read_seq(v):
    seq = []
    for i in range(2 * v):
        s = input().split()
        if len(s) == 2:
            s[1] = int(s[1])
        seq.append(s)
    return seq


def solve():
    n = int(input())
    pos = [-1] * (2 * n)
    stack = []
    seq = read_seq(n)
    for i, act in enumerate(seq):
        if act[0] == '+':
            stack.append(i)
        else:
            if not stack:
                return None
            else:
                v = stack.pop()
                pos[v] = act[1]
    if stack:
        return None

    stack = []
    for i, act in enumerate(seq):
        if act[0] == '+':
            if stack and stack[-1] < pos[i]:
                return None
            else:
                stack.append(pos[i])
        else:
            stack.pop()

    return [x for x in pos if x != -1]


def main():
    res = solve()
    if res:
        print('YES')
        print(' '.join(map(str, res)))
    else:
        print('NO')


if __name__ == '__main__':
    main()

import re

class Widget(object):
    def __init__(self, type, w = 0, h = 0):
        self.type = type
        if type == 'Widget':
            self.w = w
            self.h = h
    def calc_wh(self):
        if not hasattr(self, 'w'):
            if self.children:
                self.w = self.border * 2
                self.h = self.border * 2
                for c in self.children:
                    cw, ch = c.calc_wh()
                    if self.type == "VBox":
                        self.h += ch
                        self.w = max(self.w, cw + self.border * 2)
                    else:
                        self.w += cw
                        self.h = max(self.h, ch + self.border * 2)
                if self.type == "HBox":
                    self.w += (len(self.children) - 1) * self.spacing
                else:
                    self.h += (len(self.children) - 1) * self.spacing
            else:
                self.w = 0
                self.h = 0
        return self.w, self.h

widgets = {}

n = input()
rp = re.compile(r'(\w+)\.(\w+)\((.+)\)')

for _ in xrange(n):
  str = raw_input()
  if str.find(' ') != -1:
    type, rhs = str.split(' ')
    if type == 'Widget':
      name, other = rhs.split('(')
      w, h = map(int, other[:-1].split(','))
      widgets[name] = Widget(type, w, h)
    else:
      widgets[rhs] = Widget(type)
      widgets[rhs].children = []
      widgets[rhs].spacing = 0
      widgets[rhs].border = 0
  else:
    name, op, arg = rp.match(str).groups()
    if op == "set_border":
      widgets[name].border = int(arg)
    elif op == "set_spacing":
      widgets[name].spacing = int(arg)
    else:
      widgets[name].children.append(widgets[arg])

for k, v in sorted(widgets.items(), key = lambda x: x[0]):
    w, h = v.calc_wh()
    print k, w, h

