def readInt():
    return int(input().strip())


def readList():
    return list(map(int, input().strip().split()))


def solve(n, arrA, arrB):
    if n & 1:
        midA, midB = arrA[n//2], arrB[n//2]

        if midA != midB:
            return False

    pairsA = collections.defaultdict(int)

    for i in range(n//2):
        a1, a2 = arrA[i], arrA[n-i-1]
        pairsA[tuple(sorted([a1, a2]))] += 1

    for i in range(n//2):
        b1, b2 = arrB[i], arrB[n-i-1]

        pair = tuple(sorted([b1, b2]))

        if pair not in pairsA or pairsA[pair] == 0:
            return False

        pairsA[pair] -= 1

    return True


