    for tvshow in schedule:
        if len(tv1) == 0:
            tv1.append(tvshow)
        elif tvshow[0] > tv1[-1][1]:
            tv1.append(tvshow)
        elif len(tv2) == 0:
            tv2.append(tvshow)
        elif tvshow[0] > tv2[-1][1]:
