def digits(p,n,r = None):
    if r is None: r = [0]*n
    else: r = [x*10 for x in r]
    for i in xrange(n):
        r[-i-1]+=(p%10)
        p/=10
    return r

bx = {}
def sbx(a,b,c):
    r = 0
    for k,v in ph[a].iteritems():
        r += v*pe[k][b]
    bx[c]=r
    return r

z1 = [j%10 for j in xrange(100000)]
z2 = [j/10%10 for j in xrange(100000)]
def solve5(p,(d,a,l)):
    pd = digits(p,5)
    r = 0

    for i in d[1][pd[1]]:
        pd2 = digits(i,5,pd)
        aa,bb = pd2[4]*10, pd2[3]*10
        for j in d[2][pd2[2]]:
            a = z1[j]+aa
            b = bb+z2[j]
            c = (a<<10)|b

            if c in bx: r+=bx[c]
            else: r+= sbx(a,b,c)

    return r

def solve4(p,(d,a,l)):
    pd = digits(p,4)
    r = 0
    for i in d[1][pd[1]]:
        a = i%10+pd[3]*10
        b = i/10%10+pd[2]*10
        c = (a<<10)|b
        if c in bx: r+=bx[c]
        else: r+= sbx(a,b,c)
    return r

def solve3(p,(d,a,l)):
    pd = digits(p,3)
    a,b = pd[2],pd[1]
    r = sbx(a,b,(a<<10)|b)
    return r

def solve2(p,(d,a,l)):
    return len(d[1][p%10])

