def dfs(node, countV = 0, countE = 0):
    stack = [node]
    while stack:
        top = stack.pop()
        if not visited[top]:
            visited[top] = True
            countV += 1
            countE += len(graph[top])
            for i in graph[top]:
                if not visited[i]:
                    stack.append(i)
    return countE, countV

