mem = [-1]*(2**mhalf)

def score(bitmask):
    if bitmask==comp:
        return 0
    if mem[bitmask]==-1: 
        val = 0
        for i in range(mhalf):
            if bitmask&pow2[i]==0:
                val = max(val,score((bitmask|coupl[i])&comp))
        mem[bitmask] = val+1
    return mem[bitmask]

