    bits *= 2**mhalf
    bitmask = 0
    count = 0
    for i in range(mhalf,m):
        # check if i in bits
        if bits&pow2[i]:
            # check if none of i neighbours in bits
            if bits&coupl[i]!=pow2[i]:
                break
            bitmask |= coupl[i]
            count += 1

    else:
        # Valid bits
        count += score(bitmask&comp)
        best_count = max(best_count,count)

