				cont += 1

		if not (vog, cont) in dici:
			dici[(vog, cont)] = [word]
		else:

			dici[(vog, cont)].append(word)

	reject = {}
	other = []
	god = []

	for l in dici:
		if len(dici[l]) > 1:
			for k in xrange(len(dici[l])-1, 0, -2):
				other.append((dici[l][k], dici[l][k-1]))
				dici[l].pop()
				dici[l].pop()

	for l in dici:
		if len(dici[l]) == 1:
			if not l[1] in reject:
				reject[l[1]] = [dici[l][0]]
			else:
				reject[l[1]].append(dici[l][0])



	for l in reject:
		if len(reject[l]) > 1:
			for k in xrange(len(reject[l])-1, 0, -2):
				god.append((reject[l][k], reject[l][k-1]))
				reject[l].pop()
				reject[l].pop()

	result = []

	for k in xrange(min(len(other), len(god) )):
		result.append(other[k])
		result.append(god[k])

	final = []
	for k in xrange( 0,len(result), 2):
		final.append( (result[k+1][1], result[k][1]))
		final.append( (result[k+1][0], result[k][0]))

	if (len(god) - len(other)) % 2 == 0:
		for k in xrange(len(god), len(other), 2):
			final.append( (other[k+1][1], other[k][1]))
			final.append( (other[k+1][0], other[k][0]))
	else:
		for k in xrange(len(god) + 1, len(other), 2):
			final.append( (other[k+1][1], other[k][1]))
			final.append( (other[k+1][0], other[k][0]))

	stdout.write("%d\n" % (len(final)/2))
	for k in xrange(0, len(final), 2):
		stdout.write(final[k][0] + final[k][1])
		stdout.write(final[k+1][0] + final[k+1][1])


if __name__ == "__main__":
	main

