def main():
    n,m = map(int, raw_input().split())

    S, total = [], 0
    for i in xrange(n):
        t = map(lambda s: 1 if s == "#" else 0, raw_input())
        S.append(t)
        total += sum(t)

    if total in (1,2):
        print -1
        return

    if total == 3:
        print 1
        return

    def f():
        for i in xrange(n):
            for j in xrange(m):
                if S[i][j]: return (i,j)

    def neibors(l,r):
        for dl, dr in [(1,0), (0,1), (0,-1), (-1,0)]:
            lk, rk = l+dl, r+dr
            if (lk >= 0) and (rk >= 0) and (lk < n) and (rk < m) and S[lk][rk]:
                yield (lk, rk)

    first, used, tin, up = f(), set(), {}, {}
    def dfs((l,r), timer, p):
        used.add((l,r))
        tin[(l,r)] = up[(l,r)] = timer
        timer += 1

        childs = 0
        for lk, rk in neibors(l,r):
            if (lk,rk) == p: continue
            if (lk,rk) in used:
                up[(l,r)] = min(up[(l,r)], tin[(lk,rk)])
            else:
                timer = dfs((lk,rk), timer, (l,r))
                up[(l,r)] = min(up[(l,r)], up[(lk,rk)])
                if (up.get((lk, rk)) >= tin.get((l,r)) and p != -1):
                    print 1
                    exit(0)

                childs += 1

        if p == -1 and childs > 1:
            print 1
            exit(0)

        return timer

    dfs(first, 0, -1)
    print 2

