    if t == 1:
        for rd in path:
            if rd in cost:
                cost[rd] += p[2]
            else:
                cost[rd] = p[2]
    else:
        tot = 0
        for rd in path:
            if rd in cost:
                tot += cost[rd]

        ans.append(tot)

print("\n".join(map(str, ans)))

