def dis(ls, shifts, z):
    x, y = ls[0], ls[1]
    ans = [] 

    for shift in shifts:
        x1, y1 = shift[0], shift[1]
        a = (x - x1) ** 2
        b = (y - y1) ** 2
        d = (a + b) ** 0.5

        if d > z:
            ans.append(True)
        else:
            ans.append(False)
    if False in ans:
        return False
    else:
        return True

