    T = sorted(teams.values(), reverse=True)

    #T = sorted(T, key=attrgetter('points','difference','scored'), reverse=True)
    #print T

    n = len(T)
    T_names = [t.name for t in T[:(n/2)] ]
    return sorted(T_names)
    #return sorted(T_names, key=lambda s: (s.lower(),s))


