def rotate(x, y):
    if board[x][y] == 'L':
        board[x][y] = board[x][y+1] = 'U'
        board[x+1][y] = board[x+1][y+1] = 'D'
    else:
        board[x][y] = board[x+1][y] = 'L'
        board[x][y+1] = board[x+1][y+1] = 'R'

def fix(x, y, moves):
    if board[x+1][y] == 'U':
        if board[x+1][y+1] == 'L':
            fix(x+1, y+1, moves)
        rotate(x+1, y)
        moves.append((x+2, y+1))
    rotate(x, y)
    moves.append((x+1, y+1))

def solve_board(moves):
    global board, n, m
    board = []
    for _ in range(n):
        board.append(list(input()))
    for i in range(n-1):
        for j in range(m):
            if board[i][j] == 'L':
                fix(i, j, moves)

def main():
    global n, m
    n, m = map(int, input().split())
    moves1 = []; moves2 = []
    solve_board(moves1)
    solve_board(moves2)
