def stupid(n, ar):
    from itertools import product
    unknowns = ar.count(-1)
    print(n, end=' ')
    for consec in range(2, n+1):
        ans = 0
        for p in product(range(1+1), repeat=unknowns):
            cur = 0
            it = iter(p)
            arc = ar[:]
            for i, e in enumerate(arc):
                if e == -1:
                    arc[i] = next(it)
            prev = -1
            cnt = 0
            for x in arc:
                if x == prev:
                    cnt += 1
                else:
                    cnt = 1
                if cnt >= consec:
                    cur += 1
                    cnt = 0
                prev = x
            ans = max(ans, cur)
        print(ans, end=' ')


def solve(n, ar):
    from bisect import bisect_left

    nxt = array_of(int, 2, n+1)
    jmp = array_of(list, n+1)

    for i in reversed(range(n)):
        x = ar[i]
        nxt[0][i] = nxt[0][i+1]+1
        nxt[1][i] = nxt[1][i+1]+1
        if x == 0:
            nxt[1][i] = 0
        elif x == 1:
            nxt[0][i] = 0

    for i in range(1, n):
        for nxti in nxt:
            if nxti[i-1] == 0 and nxti[i] > 0:
                for j in range(1, nxti[i]+1):
                    jmp[j].append(i)

    debug_print(nxt)
    debug_print(jmp)

    for k in range(1, n+1):
        i = 0
        ans = 0
        while True:
            if max(nxt[0][i], nxt[1][i]) >= k:
                i += k
            else:
                idx = bisect_left(jmp[k], i)
                if idx == len(jmp[k]):
                    break
                else:
                    i = jmp[k][idx] + k
            ans += 1
        print(ans, end=' ')


def main():
    n = int(input())
    s = input()
    d = {'0': 0, '1': 1, '?': -1}
    ar = [d[c] for c in s]

    solve(n, ar)
    if LOCAL:
        print()
        stupid(n, ar)


