def lowest_prime_divisor(x, sorted_primes_to_check=primes, cache=primes_cache):
        if x in cache:
		return cache[x]
	for i in sorted_primes_to_check:
                if i * i > x:
			cache[x] = x
                        return x
                elif not x % i:
			cache[x] = i
                        return i
	cache[x] = x
        return x

