        u = p[x]
        if not f[x] and i - u >= x:
            L, R = N + 1, N + x
            z = 1
            while L < R:
                if L & 1:
                    if b[L] <= u:
                        z = 0
                        break
                    L += 1
                if R & 1:
                    R -= 1
                    if b[R] <= u:
                        z = 0
                        break
                L /= 2
                R /= 2
            f[x] = z
        p[x] = i
        x += N
        b[x] = i
        while x > 1:
            x /= 2
            b[x] = b[x+x+1]
            if b[x] > b[x+x]:
                b[x] = b[x+x]
    for x in xrange(2, n + 2):
        u = p[x]
        if not f[x] and n - u >= x:
            L, R = N + 1, N + x
            z = 1
            while L < R:
