                        z = 0
                        break
                    L += 1
                if R & 1:
                    R -= 1
                    if b[R] <= u:
                        z = 0
                        break
                L /= 2
                R /= 2
            f[x] = z
        if not f[x]:
            print x
            return
    print n + 2
