def ask(l,r):
    print("? %d %d"%(l,r))
    sys.stdout.flush()
    return int(input())

def reverse(l,r):
    for i in range(l,r+1):
        flipped[i]^=1

def flip(l,r,cur):
    global m
    while True:
        ones=0
        for i in range(l):
            ones+=flipped[i]^ans[i]
        expect=n-m-l+2*ones#expected 1s if the right segment will be flipped
        res=ask(l+1,r+1)
        if res==expect:
            reverse(l,n-1)
            m=res
        else:
            if l!=cur:
                ones+=flipped[l]^ans[l]
            if res==m-ones*2+cur-1:
                ans[cur]=1^flipped[cur]
            else:
                ans[cur]=flipped[cur]
            reverse(0,r)
            m=res
            break

