class UnionFind:
    def __init__(self, n):
        self.ps = [-1] * (n + 1)

    def find(self, x):
        if self.ps[x] < 0:
            return x
        else:
            self.ps[x] = self.find(self.ps[x])
            return self.ps[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return False
        if self.ps[x] > self.ps[y]:
            x, y = y, x
        self.ps[x] += self.ps[y]
        self.ps[y] = x
        return True

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def size(self, x):
        x = self.find(x)
        return -self.ps[x]


def solve():
    n = ni()
    uni = [UnionFind(n), UnionFind(n)]
    for _ in range(n-1):
        u, v, c = nm()
        u -= 1; v -= 1
        uni[c].unite(u, v)
    ans = 0
    for c in range(2):
        for i in range(n):
            if uni[c].find(i) == i:
                v = uni[c].size(i)
                ans += v * (v-1)
    for i in range(n):
        # print(i, (uni[0].size(i), uni[1].size(i)))
        ans += (uni[0].size(i) - 1) * (uni[1].size(i) - 1)
    print(ans)
    return

