def check_cycle():
    def cycle(u):
        mk.add(u)
        for v in xrange(n):
            if g[u][v]:
                g[u][v] -= 1
                g[v][u] -= 1
                if v in mk or cycle(v):
                    return True
        return False

    mk = set()
    cycle_num = 0
    for i in xrange(n):
        if i in mk:
            continue
        if cycle(i):
            cycle_num += 1
    if cycle_num == 1 and deg.count(2) == n:
        return True
    return cycle_num == 0

