def fnxn(n):
    n1 = n
    ans = 0
    while n:
        if n in dp:
            ans += dp[n]
            n = 0
        elif n%4 == 0:
            ans += 1
            n -= 2
        elif n%2 == 0:
            n//=2
            ans += n
            n -= 1
        else:
            ans += 1
            n -= 1
    dp[n1] = ans
    return ans

