def fill(i, j, idx):
	q = []
	def put(i, j):
		if i >= 0 and i < n and j >= 0 and j < m and lab[i][j] == -2:
			lab[i][j] = idx
			q.append((i, j))
			return 1
		return 0
	cnt = put(i, j)
	while q:
		i, j = q.pop()
		cnt = cnt + put(i - 1, j) + put(i + 1, j) + put(i, j - 1) + put(i, j + 1)
	return cnt

