class LazySegmentTree:
    def __init__(self, n, padding = 0, func=max):
        """initialize the lazy segment tree with data"""
        self._func = func
        self._len = n
        self._size = _size = 1 << (self._len - 1).bit_length()
        self.data = [padding] * (2 * _size)
        self._lazy = [0] * (2 * _size)
    def _push(self, idx):
        """push query on idx to its children"""
        q = self._lazy[idx]
        self._lazy[idx] = 0
        self.data[2 * idx] += q
        self.data[2 * idx + 1] += q
        self._lazy[2 * idx] += q
        self._lazy[2 * idx + 1] += q
    def _build(self, idx):
        """make the changes to idx be known to its ancestors"""
        idx >>= 1
        while idx:
            # TODO
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1]) + self._lazy[idx]
            idx >>= 1
    def _update(self, idx):
        """updates the node idx to know of all queries applied to it via its ancestors"""
        for i in reversed(range(1, idx.bit_length())):
            self._push(idx >> i)
    def add(self, start, stop, value):
        """lazily add value to [start, stop)"""
        start = start_copy = start + self._size
        stop = stop_copy = stop + self._size
        while start < stop:
            if start & 1:
                self.data[start] += value
                self._lazy[start] += value
                start += 1
            if stop & 1:
                stop -= 1
                self.data[stop] += value
                self._lazy[stop] += value
            start >>= 1; stop >>= 1
        self._build(start_copy); self._build(stop_copy - 1)
    def query(self, start, stop, res = 0):
        """func of data[start, stop)"""
        start += self._size; stop += self._size
        self._update(start); self._update(stop - 1)
        while start < stop:
            if start & 1:
                res = self._func(res, self.data[start])
                start += 1
            if stop & 1:
                stop -= 1
                res = self._func(self.data[stop], res)
            start >>= 1; stop >>= 1
        return res
    def node_size(self, idx):
        return 1 << self._size.bit_length() - idx.bit_length()
