                    if not checked[np]:
                        checked[np] = True
                        qq.append(np)
                        Count += 1
            q = qq
        if Count%2 == 1:
            odd += 1
    if len(graph[s]) <= 1 or odd%2 == 1:
        print("Ayush")
    else:
        print("Ashish")

