                zz[x][y] = 0
def ifallin():
    for x  in range(2,4):
        for y in range(1,N+1):
            if zz[x][y] !=0: return False
    return True

def rotate():
    ex = 0
    ey = 0
    for x  in range(2,4):
        for y in range(1,N+1):
            if zz[x][y] ==0:
                ex = x
                ey = y
                break
        if ex>0: break
    if ex==0:
        return False

    tx = ex
    ty = ey
    def nextcircle(x,y):
        if x == 2:
            if y>1:
                return x,y-1
            return x+1,y
        else:
            assert x==3
            if y<N:
                return x,y+1
            return x-1,y

    tx1,ty1 = nextcircle(tx,ty)
    while  (tx1,ty1)!= (ex,ey) :
        t = zz[tx1][ty1]
        if  t !=0:
            res.append( (t, tx,ty) )
            zz[tx][ty]  = t
            zz[tx1][ty1] = 0
        tx,ty = tx1,ty1
        tx1,ty1 = nextcircle(tx,ty)

    return True

