from collections import Counter
rd = lambda: map(int, raw_input().split(' '))
n, m, k = rd()
a = [0] * n
for i in xrange(n):
    a[i] = rd()

ln = (n + m - 2) / 2
cnt = Counter()

def rec(i, j, cur):
    global cnt, ln, n, m, a

    cur ^= a[i][j]

    if i + j > ln:
        return
    if i + j == ln:
        cnt[(i, j, cur)] += 1

    if i + 1 < n:
        rec(i + 1, j, cur)
    if j + 1 < m:
        rec(i, j + 1, cur)

ans = 0
ln2 = n + m - 2 - ln
def rec2(i, j, cur):
    global cnt, ln, n, m, k, ans

    if i + j > ln2:
        return
    if i + j == ln2:
        ans += cnt[(n - i - 1, m - j - 1, cur ^ k)]

    cur ^= a[n - i - 1][m - j - 1]
    if i + 1 < n:
        rec2(i + 1, j, cur)
    if j + 1 < m:
        rec2(i, j + 1, cur)

rec(0, 0, 0)
rec2(0, 0, 0)
print ans

