def solve():
  n, l, r = map(int, raw_input().split(" "))
  a = map(int, raw_input().split(" "))
  p = map(int, raw_input().split(" "))
  zip_p_a = sorted(zip(p, a))
  c = []
  for pt, at in zip_p_a:
    if c:
      c_1 = c[-1]
      c_1 += 1
