def gcd(a,b):
    if b == 0:
        return a 
    return gcd(b, a%b) 
def extend_euclid(a,b):
    if b == 0:
        return 1,0 
    else:
        y,x = extend_euclid(b, a%b)
        y = y - (a//b)*x
        return x,y 

