ah = chull(a)
bh = chull(b)
if len(ah) == len(bh):
    if len(ah) == 2:
        if dist_sq(ah[0], ah[1]) == dist_sq(bh[0], bh[1]):
            print('YES')
        else:
            print('NO')
    else:
        da = []
        for i in range(len(ah)):
            dot_a = dot(ah[i-2], ah[i-1], ah[i-1], ah[i])
            da.append((dist_sq(ah[i], ah[i-1]), dot_a))
        db = []
        for i in range(len(bh)):
            dot_b = dot(bh[i - 2], bh[i - 1], bh[i - 1], bh[i])
            db.append((dist_sq(bh[i], bh[i-1]), dot_b))
        l = r = 0
        daab = []
        daab.extend(db)
        daab.append(-1)
        daab.extend(da)
        daab.extend(da)
        zab = z_func(daab)
        found = False
        for i in range(len(db)+1, len(daab)-len(db)+1):
            if zab[i] == len(db):
                found = True
                break
        if found:
            print('YES')
        else:
            print('NO')
else:
    print('NO')

