#!/usr/bin/env pypy
from __future__ import division, print_function

import os
import sys
from __builtin__ import xrange as range
from cStringIO import StringIO
from future_builtins import map
from heapq import heappop, heappush
from io import IOBase

import __pypy__

INF = float(10**18)


def main():
    n, m, q = map(int, input().split())

    a, b, c_ = [0] * (m + 1), [0] * (m + 1), [0] * (m + 1)
    head, nxt = [0] * (n + 1), [0] * (m + 1)
    for i in range(1, m + 1):
        a[i], b[i], c_[i] = map(int, input().split())
        nxt[i] = head[a[i]]
        head[a[i]] = i

    c = [float(ci) for ci in c_]

    dist = [INF] * (n + 1)
    dist[1] = 0.0

    queue = [(0.0, 1)]
    while queue:
        path_len, v = heappop(queue)
        if dist[v] == path_len:
            w = head[v]
            while w:
                if dist[b[w]] > dist[v] + c[w]:
                    dist[b[w]] = dist[v] + c[w]
                    heappush(queue, (dist[b[w]], b[w]))
                w = nxt[w]

    for i in range(1, m + 1):
        c[i] -= dist[b[i]] - dist[a[i]]

    res = []

    tot, tmp = 0, [0.0] * (n + 1)
    for _ in range(q):
        qi = map(int, input().split())
        if next(qi) == 1:
            v = next(qi)
            if tot:
                tmp[2:] = [INF] * (n - 1)
                pos = [[] for _ in range(tot + 1)]
                pos[0].append(1)
                for cur in range(tot + 1):
                    for w in pos[cur]:
                        if tmp[w] == cur:
                            e = head[w]
                            while e:
                                if tmp[b[e]] > cur + c[e]:
                                    tmp[b[e]] = cur + c[e]
                                    if tmp[b[e]] <= tot:
                                        pos[int(tmp[b[e]])].append(b[e])
                                e = nxt[e]

                tot = 0
                for i in range(1, m + 1):
                    c[i] -= tmp[b[i]] - tmp[a[i]]
                for i in range(2, n + 1):
                    if tmp[i] != INF:
                        dist[i] += tmp[i]

            res.append(-1.0 if dist[v] == INF else dist[v])
        else:
            num = next(qi)
            tot += num
            for l in qi:
                c[l] += 1

    print('\n'.join(str(int(x)) for x in res))


# region fastio

BUFSIZE = 8192


class FastI(IOBase):
    def __init__(self, file):
        self._fd = file.fileno()
        self._buffer = StringIO()
        self.newlines = 0

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count("\n") + (not b)
            ptr = self._buffer.tell()
            self._buffer.seek(0,
                              2), self._buffer.write(b), self._buffer.seek(ptr)
        self.newlines -= 1
        return self._buffer.readline()


class FastO(IOBase):
    def __init__(self, file):
        self._fd = file.fileno()
        self._buffer = __pypy__.builders.StringBuilder()
        self.write = lambda s: self._buffer.append(s)

    def flush(self):
        os.write(self._fd, self._buffer.build())
        self._buffer = __pypy__.builders.StringBuilder()


def print(*args, **kwargs):
    sep, file = kwargs.pop("sep", " "), kwargs.pop("file", sys.stdout)
    at_start = True
    for x in args:
        if not at_start:
            file.write(sep)
        file.write(str(x))
        at_start = False
    file.write(kwargs.pop("end", "\n"))
    if kwargs.pop("flush", False):
        file.flush()


sys.stdin, sys.stdout = FastI(sys.stdin), FastO(sys.stdout)
input = lambda: sys.stdin.readline().rstrip("\r\n")

# endregion

if __name__ == "__main__":
    main()

def f(n):
	for i in range(3,n+1,2):
		if n%i == 0:
			return i
	return n


for t in range(int(input())):
	n, k = map(int, input().split())
	if n%2 == 0:
		n += 2*k
	else:
		n += f(n)
		n += 2*(k-1)
	print(n)

