s, n = [None]*2
t = [[0]*26 for i in range(4*N)]

def combine(v):
	global t
	for i in range(26):
		t[v][i] = t[2*v][i] + t[2*v+1][i]

def build(v, tl, tr):
	if tl == tr:
		t[v][ord(s[tl])-ord('a')] += 1
	else:
		tm = (tl + tr)//2
		build(2*v, tl, tm)
		build(2*v+1, tm+1, tr)
		combine(v)

def update(v, tl, tr, pos, new_val):
	if tl == tr:
		t[v] = [0]*26
		t[v][ord(new_val)-ord('a')] += 1
	else:
		tm = (tl + tr)//2
		if pos <= tm:
			update(2*v, tl, tm, pos, new_val)
		else:
			update(2*v+1, tm+1, tr, pos, new_val)
		combine(v)

def query(v, tl, tr, l, r):
	if l > tr or r < tl:
		return [0]*26
	if l <= tl and tr <= r:
		return t[v]
	tm = (tl + tr)//2
	ans1 = query(2*v, tl, tm, l, r)
	ans2 = query(2*v+1, tm+1, tr, l, r)
	ret = [0]*26
	for i in range(26):
		ret[i] = ans1[i] + ans2[i]
	return ret

def main():
	global s, n
	s = input()
	n = len(s)
	build(1, 0, n-1)
	for _ in range(int(input())):
		arr = input().split()
		if arr[0] == '1':
			pos, c = arr[1:]
			pos = int(pos)
			update(1, 0, n-1, pos-1, c)
		else:
			l, r = map(int, arr[1:])
			temp = query(1, 0, n-1, l-1, r-1)
			ans = 0
			for ele in temp:
				ans += int(ele > 0)
			print(ans)

BUFSIZE = 8192
class FastI(IOBase):
	def __init__(self, file):
		self._fd = file.fileno()
		self._buffer = StringIO()
		self.newlines = 0

	def read(self):
		while True:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			if not b:
				break
			ptr = self.buffer.tell()
			self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
		self.newlines = 0
		return self.buffer.read()

	def readline(self):
		while self.newlines == 0:
			b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
			self.newlines = b.count("\n") + (not b)
			ptr = self._buffer.tell()
			self._buffer.seek(0, 2), self._buffer.write(
				b), self._buffer.seek(ptr)
		self.newlines -= 1
		return self._buffer.readline()
class FastO(IOBase):
	def __init__(self, file):
		self._fd = file.fileno()
		self._buffer = __pypy__.builders.StringBuilder()
		self.write = lambda s: self._buffer.append(s)

	def flush(self):
		os.write(self._fd, self._buffer.build())
		self._buffer = __pypy__.builders.StringBuilder()
def print(*args, **kwargs):
	sep, file = kwargs.pop("sep", " "), kwargs.pop("file", sys.stdout)
	at_start = True
	for x in args:
		if not at_start:
			file.write(sep)
		file.write(str(x))
		at_start = False
	file.write(kwargs.pop("end", "\n"))
	if kwargs.pop("flush", False):
		file.flush()
def gcd(x, y):
	while y:
		x, y = y, x % y
	return x
sys.stdin, sys.stdout = FastI(sys.stdin), FastO(sys.stdout)
def input(): return sys.stdin.readline().rstrip("\r\n")
if __name__ == "__main__":
	def bootstrap(cont):
		call, arg = cont.switch()
		while True:
			call, arg = cont.switch(to=continulet(
				lambda _, f, args: f(*args), call, arg))
	cont = continulet(bootstrap)
	cont.switch()
	main()

import functools
n = int(input())

nums = list(map(int, input().split()))

bits = ["{0:b}".format(num) for num in nums]

def possible(v):
    possible_vals = [
        nums[x]
        for x in range(n)
        if len(bits[x]) > v and bits[x][len(bits[x])-v-1] == '1'
    ]
    if len(possible_vals) == 0:
        return False, []
    res = functools.reduce((lambda x, y: x&y), possible_vals, pow(2, v+1)-1)
    return bool(res & ((1 << (v+1))-1) == (1 << v)), possible_vals

for x in range(30, -1, -1):
    p, vals = possible(x)
    if p:
        print(len(vals))
        print(' '.join(list(map(str, vals))))
        break

match = 0; nonmatch = 0; count = 0
def calc_match(s, t, p):
  global match
  global nonmatch
  global count
  if p == len(s)-len(t):
    return
  if p+len(t) < len(s):
    if s[p+len(t)] == '?':
      count -= 1
    elif s[p+len(t)] == t[-1]:
      match -= 1
    else:
      nonmatch -= 1
  match, nonmatch = nonmatch, match
  if p+len(t) < len(s):
    if s[p] == '?':
      count += 1
    elif s[p] == 'a':
      match += 1
    else:
      nonmatch += 1
def init_match(s, t):
  global match
  global nonmatch
  global count
  p = len(s)-len(t)
  for i in range(len(t)):
    if s[p+i] == '?':
      count += 1
    elif s[p+i] == t[i]:
      match += 1
    else:
      nonmatch += 1
