x_odd = 0
y_odd = 0
max_even = 0
x_even = 0
y_even = 0

for i in range(n):
    for j in range(n):
        node = diagonal_secondary[i + j] + diagonal_main[i - j] - matrix[i][j]

        if (i + j) % 2 == 0:
            if node > max_odd:
                max_odd = node
                x_odd = i
                y_odd = j
