import fractions
from collections import defaultdict


if __name__ == '__main__':
    n = int(raw_input())
    a = map(int, raw_input().split())
    a *= 2
    inf = min(a) - 1
    a[-1] = inf
    result = 0

    numbers_by_gcd = defaultdict(list)
    for i in xrange(1, n):
        numbers_by_gcd[fractions.gcd(i, n)].append(i)

    for d in xrange(1, n):
        if n % d != 0:
            continue
        m = [inf] * d
        for i in xrange(n):
            if a[i] > m[i % d]:
                m[i % d] = a[i]
        l = 0
        r = 0
        while l < n:
            if a[r] < m[r % d]:
                for i in numbers_by_gcd[d]:
                    if i > r - l:
                        break
                    result += min(r - i, n - 1) - l + 1
                l = r + 1
            r += 1
    print result

