def check(l, r, a, b):
    if a < 0 or b >= 2 * N:
        return 0
    def val(p):
        if p in [a, b]: return '0'
        if l <= p and p < r: return '1'
        return '-1'
    for i in range(K):
        x, y = val(A[i]), val(C[i])
        if A[i] in [a, b] or C[i] in [a, b]:
            if not eval(x + B[i] + y):
                return 0
    return 1

