import sys


def count_bits(s):
    return [s.count("0"), s.count("1")]


# 1 - in case where a >= b
# 0 - otherwise
def compare_bits_count(a, b):
    if a[0] >= b[0] and a[1] >= b[1]:
        return 1
    else:
        return 0


def subtract_bits_count(a, b):
    return [a[0] - b[0], a[1] - b[1]]


def z_function(s):
    n = len(s)
    l = 0
    r = 0
    z = [0 for x in range(n)]
    for i in range(1, n):
        z[i] = max(0, min(r - i, z[i - l]))
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l = i
            r = i + z[i]
    return z


