    print ''.join(t)
def go(s, a, b, i):
    if i != 1 and s[-i] == 0:
        return 0
    if a != 1 and s[0] == 0:
        return 0
    if b != 1 and s[a] == 0:
        return 0
    if max(a, b) < i:
        if not a == b and not (a == i - 1 and s[0] == 9) and not (b == i - 1 and s[a] == 9):
            return 0
        if s[-i] != 1:
            return 0
        t = 1
        if a == i - 1:
            for j in xrange(a-b):
                t = t * 10 + s[-a+j] - s[j]
                if t < 0 or t > 1:
                    return 0
            for j in xrange(b):
                t = t * 10 + s[-b+j] - s[a-b+j] - s[a+j]
                if t < 0 or t > 1:
                    return 0
            if t == 0:
                pp(s[:a], s[a:a+b], s[-i:])
                return 1
            return 0
        else:
            for j in xrange(b-a):
                t = t * 10 + s[-b+j] - s[a+j]
                if t < 0 or t > 1:
                    return 0
            for j in xrange(a):
                t = t * 10 + s[-a+j] - s[j] - s[a+b-a+j]
                if t < 0 or t > 1:
                    return 0
            if t == 0:
                pp(s[:a], s[a:a+b], s[-i:])
                return 1
            return 0
    else:
        if a == i:
            t = 0
            for j in xrange(i-b):
                t = t * 10 + s[-a+j] - s[j]
                if t < 0 or t > 1:
                    return 0
            for j in xrange(b):
                t = t * 10 + s[-b+j] - s[i-b+j] - s[a+j]
                if t < 0 or t > 1:
                    return 0
            if t == 0:
                pp(s[:a], s[a:a+b], s[-i:])
                return 1
            return 0
        else:
            t = 0
            for j in xrange(i-a):
                t = t * 10 + s[-b+j] - s[a+j]
                if t < 0 or t > 1:
                    return 0
            for j in xrange(a):
                t = t * 10 + s[-a+j] - s[j] - s[a+i-a+j]
                if t < 0 or t > 1:
                    return 0
            if t == 0:
                pp(s[:a], s[a:a+b], s[-i:])
                return 1
            return 0
