    s = map(int, raw_input().strip())
    l = len(s)
    mod = 10007
    t = [0] * (l + 1)
    u = [1] * (l + 1)
    for i in xrange(l):
        u[i+1] = u[i] * 10 % mod
        t[i+1] = (t[i] * 10 + s[i]) % mod
    for i in xrange(1, l - 1):
        a, b = i - 1, l - i - i + 1
        hi = (t[l] - t[l-i] * u[i]) % mod
        if 1 <= b <= i:
            if hi == (t[a] + (t[a+b] - t[a] * u[b])) % mod and go(s, a, b, i):
