        if 1 <= b <= i:
            if hi == (t[a] + (t[a+b] - t[a] * u[b])) % mod and go(s, a, b, i):
                return
            if hi == (t[b] + (t[a+b] - t[b] * u[a])) % mod and go(s, b, a, i):
                return
