class Node:
    def __init__(self):
        self.left = -1
        self.right = -1

n = int(input())
data = list(map(int, raw_input().split()))
data = list(set(data))
root = Node()

for x in data:
    current = root

    for bit in reversed(xrange(30)):

        if (x>>bit) & 1:
            if current.right == -1:
                current.right = Node()
            current = current.right

        else:
            if current.left == -1:
                current.left = Node()
            current = current.left





stack = []
stack.append((root, 29, data))
total_cost = 0
while stack:
    current, bit, remaining = stack.pop()
    if len(remaining) == 1 or bit == -1:
        continue
    right = []
    left = []
    for x in remaining:
        if (1 << bit) & x:
            right.append(x - (1 << bit))
        else:
            left.append(x)
    if len(left) == 0:
        stack.append((current.right, bit - 1, right))
        continue
    if len(right) == 0:
        stack.append((current.left, bit - 1, left))
        continue

    stack.append((current.left, bit - 1, left))
    stack.append((current.right, bit - 1, right))

    if len(left) < len(right):
        to_search = left
        search_in = current.right
    else:
        to_search = right
        search_in = current.left
    total_cost += 1 << bit
    min_cost = 1 << 30
    for x in to_search:
        current = search_in
        current_cost = 0
        for i in reversed(xrange(bit)):    
            if (x >> i) & 1:
                if current.right != -1:
                    current = current.right
                else:
                    current = current.left
                    current_cost += 1 << i
            else:
                if current.left != -1:
                    current = current.left
                else:
                    current = current.right
                    current_cost += 1 << i

        min_cost = min(min_cost, current_cost)

    total_cost += min_cost


print(total_cost)

from random import randrange

def ask(a0,b0,L):
    print("?",L,L,flush=True)
    aa=[i for i in range(a0,a0+L)]
    print(*aa,flush=True)
    aa=[i for i in range(b0,b0+L)]
    print(*aa,flush=True)
    return input()

def main():
    for _ in range(int(input())):
        n,k=map(int,input().split())
        isfirst=False
        for _ in range(30):
            if ask(1,randrange(2,n+1),1)=="SECOND":
                isfirst=True
        if isfirst:
            print("! 1",flush=True)
            continue

        ln=1
        while 1:
            ret=ask(1,1+ln,ln)
            if ret=="FIRST":
                l,r=1+ln,1+ln*2
                break
            if ln*4>n:
                l,r=1+ln*2,n+1
                break
            ln*=2

        while l+1<r:
            m=(l+r)//2
            if ask(1,l,m-l)=="EQUAL":l=m
            else:r=m

        print("!",l,flush=True)

