#!/usr/bin/env python3

# http://codeforces.com/contest/633/problem/C

from collections import deque

# import sys
# sys.setrecursionlimit(10001)

n = int(input())
s = input()
m = int(input())
words = []
for i in range(0, m):
    words.append(input())

dict_words = {}
for word in words:
    dict_words[word.lower()[::-1]] = word

trie_words = {}
for word in dict_words.keys():
    d = trie_words
    for letter in word:
        d = d.setdefault(letter, {})
    d['word'] = word

def find_sentence(s):
    # stack = [0, '', dict_words, []] # position, used words so far, pos in trie we stopped on, children
    roots = deque() # position, used words so far, pos in trie we stopped on, children

    d = trie_words
    for i in range(0, len(s)):
        if not s[i] in d:
            break;
        d = d[s[i]]
        if 'word' in d:
            word = d['word']
            new_root = [i + 1, word, None]
            roots.append(new_root)
            if i + 1 == len(s):
                return new_root

    while len(roots) > 0:
        root = roots.popleft()
        d = trie_words

        for i in range(root[0], len(s)):
            if not s[i] in d:
                break;
            d = d[s[i]]
            if 'word' in d:
                word = d['word']
                new_root = [i + 1, word, root]
                roots.appendleft(new_root)
                if i + 1 == len(s):
                    return new_root

result = find_sentence(s)
words = []
while not result is None:
    word = result[1]
