    dp = [set() for _ in xrange(N)]
    dp[0].add(0)
    prev = {}
    for k, x in enumerate(b):
        ndp = [set() for _ in xrange(N)]
        for i in xrange(N):
            if not dp[i]:
                continue
            for j in bs[x]:
                z = nz[i][j]
                for l in dp[i]:
                    nl = l + z
                    ndp[j].add(nl)
                    prev[k+1,j,nl] = (i, l)
        dp, ndp = ndp, dp
    return dp, prev
