    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def rect(a, b, c, d):
    return dist(a, b) == dist(c, d) and dist(a, c) == dist(b, d) and dist(a, d) == dist(b, c) and dist(a, b) * dist(b, c) != 0

