def win(r,c,size):
    if size==0:
        return []
    if r[-1]==c[-1]==size:
        return win(r[:-1],c[:-1],size-1)
    good=(size,c[-1],r[-1],size)
    for i in range(size):
        if r[i]==size:
            r[i]=r[-1]
        if c[i]==size:
            c[i]=c[-1]
    r.pop()
    c.pop()
    return win(r,c,size-1)+[good]
