#code_taken_from https://stoverflow.com/questions/30698441/optimal-way-to-find-sums-of-all-contiguous-sub-arrays-max-difference
def sumaaa(d):
    st = [(-1, float('inf'))]
    sum_ = 0
    for i, x in enumerate(d):
        while x > st[-1][1]:
            aa, ab = st.pop()
            aba, abb = st[-1]
            sum_ += ab * (i - aa) * (aa - aba)
        st.append((i, x))
    while len(st) > 1:
        aa, ab = st.pop()
        aba, abb = st[-1]
        sum_ += ab * (len(d) - aa) * (aa - aba)
    return sum_

def max_differences_sum(d):
    return sumaaa(d) + sumaaa([-x for x in d])
