    D = map(int, sys.stdin.readline().strip())
    Sum = 0
    c = [0] * 11
    for x in D:
        cn = [0] * 11
        if x != 0:
            cn[x] += 1
        for i in xrange(x + 1, 11):
            cn[((i - 1) * i // 2 + x + 10) % 11] += c[i]
        c = cn
        Sum += sum(c)
    cout << Sum << endl


