def solve(s, t, i, l):
    if i == l:
        return False
    if s[i] == "?":
        if solve(s, t, i + 1, l):
            s[i] = t[i]
            return True
        elif t[i] == "9":
            return False
        s[i] = nxt[t[i]]
        for j in range(i, l):
            if s[j] == "?":
                s[j] = "0"
        return True
    elif s[i] > t[i]:
        for j in range(i, l):
            if s[j] == "?":
                s[j] = "0"
        return True
    elif s[i] < t[i]:
        return False
    else:
        return solve(s, t, i + 1, l)


