LEN=n

BIT=[0]*(LEN+1)

def update(v,w):
    while v<=LEN:
        BIT[v]+=w
        v+=(v&(-v))

def getvalue(v):
    ANS=0
    while v!=0:
        ANS+=BIT[v]
        v-=(v&(-v))
    return ANS

def bisect_on_BIT(x):

    if x<=0:
        return 0

    ANS=0
    h=1<<(LEN.bit_length()-1)
    while h>0:
