from sys import stdin
from collections import defaultdict
def emp(l, a):
    cnt = pos = x = 0
    for y in a:
        if y[1]:
            cnt -= 1
        else:
            if not cnt:
                x += y[0] - pos
            cnt += 1
        pos = y[0]
    x += l - pos
    return x
def check(x, b):
    return x ^ b < x
def f(x, b):
    return x - (x ^ b)
