def add(a, b):
    out = [0] * (max(len(a), len(b)))
    for i in range(len(a)):
        out[i] = a[i]
    for i in range(len(b)):
        out[i] += b[i]
        out[i] %= MOD
    return out


def addSh(a, b):
    out = [0] * (max(len(a) + 1, len(b)))
    for i in range(len(a)):
        out[i + 1] = a[i]
    for i in range(len(b)):
        out[i] += b[i]
        out[i] %= MOD
    return out

