from __future__ import division
from fileinput import input
from itertools import izip

class KMP:
    def __init__(self, pattern):
        pass

    def KnuthMorrisPratt(self, text, pattern):
        '''Yields all starting positions of copies of the pattern in the text.
    Calling conventions are similar to string.find, but its arguments can be
    lists or iterators, not just strings, it returns all matches, not just
    the first one, and it does not need the whole text in memory at once.
    Whenever it yields, it will have read the text exactly up to and including
    the match that caused the yield.'''

        # allow indexing into pattern and protect against change during yield
        pattern = list(pattern)

        # build table of shift amounts
        shifts = [1] * (len(pattern) + 1)
        shift = 1
        for pos in range(len(pattern)):
            while shift <= pos and pattern[pos] != pattern[pos-shift]:
                shift += shifts[pos-shift]
            shifts[pos+1] = shift

        # do the actual search
        startPos = 0
        matchLen = 0
        for c in text:
            while matchLen == len(pattern) or \
                  matchLen >= 0 and pattern[matchLen] != c:
                startPos += shifts[matchLen]
                matchLen -= shifts[matchLen]
            matchLen += 1
            if matchLen == len(pattern):
                return startPos
        return -1


def alleq(li):
    for c in li[1:]:
        if c != li[0]:
            return False
    return True

def mkst(r):
    out = ""
    for c in r:
        out += c
    return out

def solve():
    inp = input()
    n = int(inp.readline())
    fro = []
    for _ in xrange(n):
        line = inp.readline().rstrip("\n")
        fro.append(line)
    to = []
    for _ in xrange(n):
        line = inp.readline().rstrip("\n")
        to.append(line)

    changefrom = ""
    changeto = ""
    nochange = []
    changearr = []
    fronts = []
    backs = []
    for f, t in zip(fro, to):
        errors = -1
        errore = -1
        for i in xrange(len(f)):
            if f[i] != t[i]:
                if errors == -1:
                    errors = i
                errore = i
        if errors == -1:
            nochange.append(f)
            continue
        cf = f[errors:errore + 1]
        ct = t[errors:errore + 1]

        if changefrom == "":
            changefrom = cf
            changeto = ct
        else:
            if cf != changefrom or ct != changeto:
                return "NO"
        changearr.append((f, errors,errore, t))
        fronts.append(f[0:errors])
        backs.append(f[errore + 1:])
    front = ""
    i = 1
    cont = True
    while cont:
        if i > len(fronts[0]):
            break
        else:
            th = fronts[0][-i]
        for st in fronts:
            if i > len(st):
                cont = False
                break
            if st[-i] != th:
                cont = False
                break
        else:
            front += th
        i += 1

    front = mkst(reversed(front))

    back = ""
    for cs in izip(*backs):
        if alleq(cs):
            back += cs[0]
        else:
            break
    changefrom = front + changefrom + back

    ford, errors, errore, toord = changearr[0]
    changeto = toord[errors - len(front): errors] + changeto + toord[errore + 1: errore + 1 + len(back)]
    kmp = KMP(changefrom)
    for f, errors, errore, t in changearr:
        if kmp.KnuthMorrisPratt(f, changefrom) + len(front) != errors:
             return "NO"

    for st in nochange:
        if kmp.KnuthMorrisPratt(st, changefrom) != -1:
            return "NO"
    return "YES\n" + changefrom + "\n" + changeto


print solve()

