import Queue

inFile = open("input.txt", 'r')
outFile = open("output.txt", 'w')

n, m, d = map(int, inFile.readline().strip().split(' '))
mat = map(lambda x: x.strip(), inFile.readlines())
mv = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def findRats():
    ret = []
    for i in xrange(n):
        for j in xrange(m):
            if mat[i][j] == 'R':
                ret.append((i, j))
    return ret

def bfs(bgn, mat, d):
    q = Queue.Queue()
    q.put(bgn)
    c = {bgn:0}
    ret = set()
    while not q.empty():
        now = q.get()
        ret.add(now)
        if c[now] < d:
            for mi in mv:
                then = (now[0] + mi[0], now[1] + mi[1])
                if then[0] < n and then[0] >= 0 and \
                        then[1] < m and then[1] >= 0:
                    if mat[then[0]][then[1]] != 'X':
                        if then not in c:
                            q.put(then)
                            c[then] = c[now] + 1
    return ret

def find(firsts, locs):
    for first in firsts:
        others = []
        for loc in locs:
            if first not in loc:
                others.append(loc)
        if len(others) == 0:
            ans = [first]
            for i in xrange(n):
                for j in xrange(m):
                    if (i, j) != first:
                        if mat[i][j] != 'X':
                            ans.append((i, j))
                            return ans
            return -1
        seconds = reduce(lambda x, y: x & y, others)
        for second in seconds:
            if second != first:
                return (first, second)
    return -1

rats = findRats()
if len(rats) > ((d + 1) * 2) ** 2:
    outFile.write('-1\n')
else:
    locs = []
    for r in rats:
        locs.append(bfs(r, mat, d))
    ans = find(locs[0], locs[1:])
    if ans == -1:
        outFile.write('-1\n')
    else:
        outFile.write("{:d} {:d} {:d} {:d}". \
                          format(ans[0][0] + 1,
                                 ans[0][1] + 1,
                                 ans[1][0] + 1, 
                                 ans[1][1] + 1))

def combinacoes(x):
    # Se for apenas 1 elemento retorna 1 arranjo
    if x == 1:
        return [[0]]
    else:
        # Adiciona os elementos a lista auxiliar
        aux = combinacoes(x - 1)
    pilha = []
    par = 0
    # Percorre a lista juntando os elementos nas possibilidades possíveis
    for element in aux:
        lmt = max(element) + 1
        if par == 0:
            for j in range(lmt + 1):
                pilha.append(element + [j])
        else:
            # Range invertido
            for j in range(lmt + 1)[::-1]:
                pilha.append(element + [j])
        par = par ^ 1
    return pilha


