        for j in range(1, 27):
            if num[j] > 0:
                mcmf.AddArcWithCapacityAndUnitCost(26 + i, j, num[j], i)
    mcmf.SetNodeSupply(source, 1 << 63)
    mcmf.SetNodeSupply(sink, -(1 << 63))
    mcmf.Solve()
    if mcmf.OptimalFlow() != length:
        print("-1")
    else:
        print(mcmf.OptimalCost())


