def solve(N, A):
    graph = [set() for _ in xrange(N)]
    rgraph = [set() for _ in xrange(N)]

    for u, row in enumerate(A):
        for v, val in enumerate(row):
            if val:
                graph[u].add(v)
                rgraph[v].add(u)

    # Try to write row 0 in terms of row i
    stack, seen = [0], {0}
    while stack:
        node = stack.pop()
        for nei in graph[node]:
            if nei not in seen:
                seen.add(nei)
                stack.append(nei)
    if len(seen) != N:
        return False

    # Try to write row i in terms of row 0
    stack, seen = [0], {0}
    while stack:
        node = stack.pop()
        for nei in rgraph[node]:
            if nei not in seen:
                seen.add(nei)
                stack.append(nei)
    return len(seen) == N


