def getstr(n):
    if n==1:
        return 'a','',1
    elif n==2:
        return 'ab','b',2
    else:
        if n%2==0:
            p,u,now=getstr((n-2)//2)
            c = chr(ord('a')+now)
            return p+c,c+u+c+c,now+1
        else:
            p,u,now=getstr((n-1)//2)
            c = chr(ord('a')+now)
            return p+c,u+c+c,now+1


