import math as mt 
from sys import stdin,stdout

MAXN = 10000001
spf = [0]*(MAXN) 

def sieve(): 
	spf[1] = 1
	for i in range(2, MAXN):
		spf[i] = i
	for i in range(4, MAXN, 2): 
		spf[i] = 2
	for i in range(3, mt.ceil(mt.sqrt(MAXN))): 
		if (spf[i] == i):
			for j in range(i * i, MAXN, i):
				if (spf[j] == j): 
					spf[j] = i 

def getFactorization(x): 
	ret = list() 
	while (x != 1): 
		ret.append(spf[x]) 
		x = x // spf[x] 
	return ret 
sieve() 


