class DisjointSetUnion0:
    def __init__(self, n):
        self.data = [-1] * n

    def __getitem__(self, a):
        acopy = a
        while self.data[a] >= 0:
            a = self.data[a]
        while acopy != a:
            self.data[acopy], acopy = a, self.data[acopy]
        return a

    def __call__(self, a, b):
        a, b = self[a], self[b]
        if a != b:
            if self.data[a] > self.data[b]:
                a, b = b, a

            self.data[a] += self.data[b]
            self.data[b] = a

class DisjointSetUnion1:
    def __init__(self):
        self.data = collections.defaultdict(lambda: -1)

    def __getitem__(self, a):
        acopy = a
        while self.data[a] >= 0:
            a = self.data[a]
        while acopy != a:
            self.data[acopy], acopy = a, self.data[acopy]
        return a

    def __call__(self, a, b):
        a, b = self[a], self[b]
        if a != b:
            if self.data[a] > self.data[b]:
                a, b = b, a

            self.data[a] += self.data[b]
            self.data[b] = a
            return True
        return False

