def main():
    n = int(input())
    p = [int(e) for e in input().split()]

    prev = 0
    items = [0]
    for i in range(1, 2 * n):
        if p[i] > p[prev]:
            items.append(i - prev)
            prev = i

    weights = {0}
    for item in items:
        new_weights = set(weight + item for weight in weights if weight + item <= n)
        weights = weights.union(new_weights)
        if n in weights:
            print("YES")
            return

    print("NO")


