            if (pos + pw <= n) and (st[pos + pw-1] < s):
                pos += pw
                s -= st[pos-1]
            pw //= 2
        return pos

    def insert(i):
        update(i, +1)

    def remove(i):
        update(i, -1)

    def find_by_order(i):
        return lower_bound(i)

    def order_of(i):
        return query(i)

    def lr(i):
        o = order_of(i)
        l = find_by_order(o)
        r = find_by_order(o+1)
        return l, r

