def doWork(input):
    n,m,s = input
    r = s.copy()
    if n > 1:
        for _ in range(m):
            if s[0] == '0' and s[1] == '1':
                r[0] = '1'
            if s[-1] == '0' and s[-2] == '1':
                r[-1] = '1'            
            for i in range(1,n-1):
                if s[i] == '0' and s[i-1] == '1' and s[i+1] == '0':
                    r[i] = '1'
                if s[i] == '0' and s[i+1] == '1' and s[i-1] == '0':
                    r[i] = '1'   
            if s == r:
                break
            else:                 
                s = r.copy()
    else:
        r = s
    return ''.join(r)


