def getMinDists(inputs):
    resX = [None] * len(inputs)
    resY = [None] * len(inputs)

    for (inpIdx, inp) in enumerate(inputs):
        for (y, row) in enumerate(inp):
            for (x, char) in enumerate(row):
                if char == 'R':
                    resX[inpIdx] = min(resX[inpIdx], x) if resX[inpIdx] is not None else x
                    resY[inpIdx] = min(resY[inpIdx], y) if resY[inpIdx] is not None else y

    return (resX, resY)

def passTest(inputs, xMins, yMins):
    for (idx, inp) in enumerate(inputs):
        print('YES' if inp[yMins[idx]][xMins[idx]] == 'R' else 'NO')

