        st.pop()
        g[n].append(pidx)
        ginv[pidx].append(n)
    degree = [0] * (n + 1)
    st = []
    for i in range(n + 1):
        degree[i] = len(g[i])
        if degree[i] == 0:
            st.append(i)
    dp = [None] * (n + 1)
    MOD = int(1e9 + 7)
    while st:
        x = st[-1]
        st.pop()
        if g[x]:
            vec = g[x]
            d = dp[vec[0]]
            for i in range(1, m + 2):
                d[i] = (d[i] + d[i - 1]) % MOD
            for j in range(1, len(vec)):
                dd = dp[vec[j]]
                nd = [0] * (m + 2)
                for i in range(1, m + 2):
                    nd[i] = (dd[i] * d[i] + nd[i - 1]) % MOD
                d = nd
            d.insert(0, 0)
            d.pop()
        else:
            d = [1] * (m + 2)
            d[0] = 0
        dp[x] = d
        for v in ginv[x]:
            degree[v] -= 1
            if degree[v] == 0:
                st.append(v)
    print(dp[n][m + 1])

def main():
    for i in range(int(sys.stdin.readline())):
        solve()


if __name__ == '__main__':
    main()

