best_length, best_pos = 0, 0

def kosher(left, right):
    pos_range = range(right - 1, left - 1, -1)
    for key in keys:
        if len(key) > right - left:
            continue
        for pos in pos_range:
            key_pos = len(key) - right + pos
            if key_pos == -1 or key[key_pos] != s[pos]:
                break
            if key_pos == 0:
                return False
    return True

left, right = 0, 0
while True:
        if kosher(left, right + 1):
            right += 1
            length = right - left
            if length > best_length:
                best_length = length
                best_pos = left
            if right == len(s):
                break
        else:
            left += 1

print('%d %d' % (best_length, best_pos))

