def answer():

    left , right = [] , []

    j = 0
    for i in range(n - 1):

        if(query2(i + 1 , i + 2) != 1):
            left.append(j)
            right.append(i)

            j = i + 1

    left.append(j)
    right.append(n - 1)

    ans = []
    ch = query1(1)
    for i in range(left[0] , right[0] + 1):
        ans.append(ch)

    pos = [[0 , ch]]
    for i in range(1 , len(left)):

        l , h = 0 , len(pos) - 1

        what = left[i]
        while(l <= h):

            mid = (l + h)//2

            if(query2(pos[mid][0] + 1 , right[i] + 1) != len(pos) - mid + 1):
                what = pos[mid][0]
                ch = pos[mid][1]
                l = mid + 1
            else:
                h = mid - 1

        if(what == left[i]):

            ch = query1(what + 1)
            pos.append([what , ch])
            for j in range(left[i] , right[i] + 1):
                ans.append(ch)

        else:

            pos.remove([what , ch])
            pos.append([left[i] , ch])

            for j in range(left[i] , right[i] + 1):
                ans.append(ch)

        pos.sort()

    return ''.join(ans)



