def maxsparse(a):
	l = []
	l.append(a)
	c = 1
	while c < len(a):
		new = []
		for i in range(len(a)):
			if i + c < len(l[-1]):
				new.append(max(l[-1][i], l[-1][i + c]))
			else:
				break
		l.append(new)
		c *= 2
	return l

def partial(table, i, j):
	if j <= i:
		return -1000000
	yyy = 1
	aaa = 0
	while 2 * yyy <= j - i:
		yyy *= 2
		aaa += 1
	return max(table[aaa][i], table[aaa][j - yyy])

