import sys
import math

TEST_MODE = False

def step():
    global vals
    next_vals = [0] * N
    for j in range(N):
        if j != special:
            next_vals[(j - 1 + N) % N] += vals[j] // 2
            next_vals[(j + 1) % N] += vals[j] - (vals[j] // 2)
        else:
            next_vals[(j + 1) % N] += vals[j]
    vals = next_vals
    if N <= 100:
        print(vals)

def fix(z):
    z %= N
    while z > N:
        z -= N
    while z <= 0:
        z += N
    return z

nq = 0
def query(q):
    global nq
    nq += 1
    print("? " + str(q))
    sys.stdout.flush()

    if TEST_MODE:
        res = vals[q - 1]
        print(res)
        step()
        return res

    res = int(input())
    return res

if TEST_MODE:
    N, K, special = map(int, input().split())
    special -= 1

    vals = [K] * N
else:
    N, K = map(int, input().split())

THRESH = int(math.sqrt(N)) if N >= 100 else 1
for i in range(THRESH):
    query(1)

for i in range(N // THRESH + 2):
    q = fix(i * THRESH)
    h = query(q)
    if h != K:
        begin = q
        break

def submit(q):
    print("! " + str(q))
    if TEST_MODE:
        if special + 1 == q:
            print('GOOD', nq)
        else:
            print('BAD', nq)
    sys.stdout.flush()
    sys.exit(0)

def attempt(q):
    z = query(q)
    if z == K:
        submit(q)

i = 0
delta = 1 if h < K else -1
while True:
    q = fix(begin + delta * (i + 1))
    z = query(q)
    if z == K:
        submit(q)
    elif (z < K) != (h < K):
        attempt(fix(q - 1))
        attempt(fix(q - 2))
    i += 3

