def getCoordinateCompressMap(arr): # returns {number : compressed number}
    nums = sorted(set(arr))
    mapp = {x : i for i, x in enumerate(nums)}
    return mapp

class SegmentTree():
    def __init__(self,arr,combinerFunction,isCommutative=True): # isCommutative means f(a,b)==f(b,a)
        self.n=len(arr)
        def cmb(a,b):
            if a==None: return b
            if b==None: return a
            return combinerFunction(a,b)
        self.cmb=cmb
        self.sz=self.n if isCommutative else pow(2,((self.n-1).bit_length())) # non-commutative needs power of 2 size
        self.t=[None]*(2*self.sz) # use None as initial value
        for i in range(self.n): self.t[i+self.sz]=arr[i]
        for i in range(self.sz-1,0,-1): self.pull(i)
    def pull(self,p):
        self.t[p]=self.cmb(self.t[2*p],self.t[2*p+1])
    def update(self,idx,val): # set val at idx
        idx+=self.sz
        self.t[idx]=val
        idx//=2
        while idx>0:
            self.pull(idx)
            idx//=2
    def query(self,l,r): # aggregated value in [l,r] inclusive
        l+=self.sz; r+=self.sz+1
        a=b=None
        while l<r:
            if l%2==1: a=self.cmb(a,self.t[l]); l+=1
            if r%2==1: r-=1; b=self.cmb(self.t[r],b)
            l//=2; r//=2
        return self.cmb(a,b)
def getMaxSegTree(arr):
    return SegmentTree(arr,lambda a,b:max(a,b),True)
def getMinSegTree(arr):
    return SegmentTree(arr,lambda a,b:min(a,b),True)
def getSumSegTree(arr):
    return SegmentTree(arr,lambda a,b:a+b,True)


def main():

    t = int(input())
    allans = []
    for _ in range(t):
        n = int(input())
        a = readIntArr()

        prefix_sums = a.copy()
        for i in range(1, n):
            prefix_sums[i] += prefix_sums[i - 1]
        mapp = getCoordinateCompressMap(prefix_sums + [0])
        prefix_sums_compressed = [mapp[x] for x in prefix_sums]
        # pad everything by 1
        for i in range(n):
            prefix_sums_compressed[i] += 1
        maxN = max(prefix_sums_compressed)
        maxN += 5

        st1 = getMaxSegTree([-int(2e9)] * maxN) # for s > 0. stores v + i
        st2 = getMaxSegTree([-int(2e9)] * maxN) # for s < 0. stores v - i
        equal_checker = [-int(2e9)] * maxN # for s == 0. stores v

        # initialize for i = -1 and sum = 0
        zero_compressed = mapp[0] + 1 # padded by 1
        st1.update(zero_compressed, 1)
        st2.update(zero_compressed, -1)
        equal_checker[zero_compressed] = 0

        dp = [-int(2e9)] * n

        for r, x in enumerate(a):
            p = prefix_sums_compressed[r]
            v1 = st1.query(0, p - 1) + r
            v2 = st2.query(p + 1, maxN - 1) - r
            v3 = equal_checker[p]
            v = max(v1, v2, v3)
            dp[r] = v

            if st1.query(p, p) < v - r:
                st1.update(p, v - r)
            if st2.query(p, p) < v + r:
                st2.update(p, v + r)
            equal_checker[p] = max(equal_checker[p], v)

        ans = dp[n - 1]
        allans.append(ans)
    multiLineArrayPrint(allans)

    return

