def finder(A, x, l, r):
    if A[r] < x:
        return r+1
    if A[l] >= x:
        return l
    s = l 
    e = r
    #A[s] < x <= A[e]
    while s+1 < e:
        m = (s+e)//2
        if A[m] < x:
            s, e = m, e
        else:
            s, e = s, m
    return e

def process(A):
    n = len(A)
    if n <= 2 or A[-1]==A[0]:
        sys.stdout.write(f'0\n')
        return
    answer = n-2
    for s in range(n):
        if s==0 or A[s] > A[s-1]:
            entry = s
            if s >= answer:
                break
            s1 = s+1
            while s1+1 < n:
                x = 2*A[s1]-A[s]
                s2 = finder(A, x, s1+1, n-1)
                entry+=(s2-s1-1)
                if entry >= answer:
                    break
                s1 = s2
            answer = min(answer, entry)
    print(answer)
    return

