def solve(N, M, X, A):
    # N - num students
    # M - num questions
    # X[i] num points ith student expects
    # A[i][j] = ith student has answered jth q correct

    ans = -1
    for mask in xrange(1 << N):
        constant = 0
        coeffs = [0] * M
        for i, row in enumerate(A):
            if mask >> i & 1:  # positive
                for j, x in enumerate(row):
                    if x:
                        coeffs[j] += 1
                constant -= X[i]
            else:
                for j, x in enumerate(row):
                    if x:
                        coeffs[j] -= 1
                constant += X[i]

        coeffs.sort()
        for i, c in enumerate(coeffs, 1):
            constant += c * i
        if constant > ans:
            ans = constant
            ansf = mask

    mask = ansf
    constant = 0
    coeffs = [0] * M
    for i, row in enumerate(A):
        if mask >> i & 1:  # positive
            for j, x in enumerate(row):
                if x:
                    coeffs[j] += 1
            constant -= X[i]
        else:
            for j, x in enumerate(row):
                if x:
                    coeffs[j] -= 1
            constant += X[i]
    B = sorted([x, i] for i,x  in enumerate(coeffs))
    ans = [0] * M
    for index, (x, i) in enumerate(B , 1):
        ans[i] = index
    return ans

