def power(bottom, up):
    # print(bottom, up)
    if up == 1:
        return bottom
    elif up == 0:
        return 1
    tmp = power(bottom, int(up // 2))
    if up % 2 == 0:
        return (tmp * tmp)
    else:
        return (tmp * tmp * bottom)


