def bs_pred_r(predicate, start_l, start_r):
    l = start_l
    r = start_r
    while l <= r:
        mid = (l&r+1) + ((l^r+1)>>1)
        if predicate(mid):
            r = mid-1
        else:
            l = mid+1
    return l

def build_ranges(x,y,k):
    res = []

    c = 0
    prev = 0
    rem = k
    for i,val in enumerate(A):
        if x <= val <= y:
            c += 1
        if rem > 1:
            sz = i - prev + 1
            if c > sz//2:
                c = 0
                rem -= 1
                res.append((prev,i))
                prev = i+1

    res.append((prev,N-1))

    return res

def solve():

    c = [0] * (N+1)
    for val in A:
        c[val] += 1

    pref = [0] * (N+1)
    for i in range(1,N+1):
        pref[i] += pref[i-1] + c[i]

    x = -10**9
    y = 10**9
    for i,val in enumerate(pref):
        q = K-1 + (N-K+1)//2 + 1
        if val < q:
            continue
        d = val - q + 1
        pred = lambda x: pref[x] >= d
        l = bs_pred_r(pred, 0, N)
        if i-l < y-x:
            x = l
            y = i

    res = build_ranges(x, y, K)

    return str(x) + " " + str(y) + "\n" + "\n".join(str(a+1) + " " + str(b+1) for a,b in res)

