# Based on https://codeforces.com/contest/1567/submission/127989410
# But use ffi for data layout and use double instead of big integer for answer

import sys
from cffi import FFI

input = sys.stdin.buffer.readline

ffi = FFI()
ffi.cdef(
    """
    typedef struct {
        int first;
        int last;
        int suf;
        int pre;
        int length;
        double ans;
    } node_t;
    """
)




MX = 2 << ((2 * 10 ** 5) - 1).bit_length()
data = ffi.new("node_t[]", MX + 3)
data[MX] = (0, 0, 0, 0, 0, 0)
id_node = data[MX]
res_left = MX + 1
res_right = MX + 2



def combine(a, b):
    if a.length == 0:
        return b
    if b.length == 0:
        return a
    first = a.first
    last = b.last
    suf = 0
    pre = 0
    length = a.length + b.length
    ans = a.ans + b.ans
    if a.last <= b.first:
        if a.length == a.pre:
            pre = b.pre + a.length
        else:
            pre = a.pre
        if b.length == b.suf:
            suf = a.suf + b.length
        else:
            suf = b.suf
        ans += a.suf * b.pre
    else:
        pre = a.pre
        suf = b.suf
    return (first, last, suf, pre, length, ans)


def mapValue(x):
    return (x, x, 1, 1, 1, 1)


class SegmentTree:
    def __init__(self, N, A):
        self._len = N
        self._size = _size = 1 << (self._len - 1).bit_length()
        for i in range(2 * _size):
            data[i] = id_node
        for i, x in enumerate(A):
            data[_size + i] = mapValue(x)
        for i in reversed(range(_size)):
            data[i] = combine(data[i + i], data[i + i + 1])

    def __delitem__(self, idx):
        self[idx] = id_node

    def __getitem__(self, idx):
        return data[idx + self._size]

    def __setitem__(self, idx, value):
        idx += self._size
        data[idx] = value
        idx >>= 1
        while idx:
            data[idx] = combine(data[2 * idx], data[2 * idx + 1])
            idx >>= 1

    def __len__(self):
        return self._len

    def query(self, start, stop):
        """func of data[start, stop)"""
        start += self._size
        stop += self._size
        data[res_left] = id_node
        data[res_right] = id_node
        while start < stop:
            if start & 1:
                data[res_left] = combine(data[res_left], data[start])
                start += 1
            if stop & 1:
                stop -= 1
                data[res_right] = combine(data[stop], data[res_right])
            start >>= 1
            stop >>= 1
        data[res_left] = combine(data[res_left], data[res_right])
        return data[res_left]


def main():
    n, q = map(int, input().split())
    segtree = SegmentTree(n, map(int, input().split()))
    ans = []
    for _ in range(q):
        t, l, r = map(int, input().split())
        l -= 1
        if t == 1:
            segtree[l] = mapValue(r)
        else:
            ans.append(int(segtree.query(l, r).ans))
    print("\n".join(map(str, ans)))


if __name__ == "__main__":
    main()

