def ans(A, B):
    A = clean(A)
    B = clean(B)

    A = [bin(x) for x in A]
    B = [bin(x) for x in B]

    t = BinaryTrie_pool()

    for b in B:
        t.insert(b)

    for a in A:
        w = t.findAnyWithPrefix(a)

        if w is None:
            return "NO"

        t.removeAnyWithPrefix(a)

    return "YES"

