from sys import stdin, stdout
N = 998244353

def toposort(graph):
    res, found = [], [0] * len(graph)
    stack = list(range(len(graph)))
    while stack:
        node = stack.pop()
        if node < 0:
            res.append(~node)
        elif not found[node]:
            found[node] = 1
            stack.append(~node)
            stack += graph[node]

    # cycle check
    for node in res:
        if any(found[nei] for nei in graph[node]):
            return None
        found[node] = 0

    return res[::-1]

t = int(stdin.readline())

for _ in range(t):
    n, m = [int(x) for x in stdin.readline().split()]
    a = [int(x) for x in stdin.readline().split()]
    in_neighbours = {i:set() for i in range(n)}
    out_neighbours = {i:set() for i in range(n)}

    for bar in range(m):
        v, w = [int(x)-1 for x in stdin.readline().split()]
        in_neighbours[w].add(v)
        out_neighbours[v].add(w)

    if max(a) == 0:
        stdout.write('0\n')

    else:
        time = 0

        success = False
        for bar in range(n-1):
            time += 1
            delta = []
            for v in range(n):
                if a[v] == 0:
                    temp = 0
                else:
                    temp = -1

                for w in in_neighbours[v]:
                    if a[w] > 0:
                        temp += 1

                delta.append(temp)

            for v in range(n):
                a[v] += delta[v]

            if max(a) == 0:
                success = True
                break

        if success:
            stdout.write(str(time)+'\n')

        else:
            stack = toposort(out_neighbours)
            for v in stack:
                for w in out_neighbours[v]:
                    a[w] = (a[w]+a[v])%N

            stdout.write(str((time+a[v])%N)+'\n')

