def gen_z(s, zx = None, x=None):
    z = [0]*len(s)
    l, r, start = 0, -1, 0
    if not zx: zx = z; x =s; z[0] = len(s); start = 1
    for i in range(start, len(s)):
        if i <= r: z[i] = min(zx[i - l], r - i + 1);
        while i + z[i] < len(s) and z[i] < len(x) and s[i + z[i]] == x[z[i]]: z[i]+=1;
        if i + z[i] - 1 > r:
            l = i;
            r = i + z[i] - 1;
    return z

