from collections import deque
def radix_sort(a):
    l = len(a)
    arr = [[a[i], i] for i in range (l)]
    mx = max(a)
    m = 0
    while mx > 0:
        mx = mx // 10
        m += 1
    bucket = [deque([]) for _ in range (10)]
    for _ in range (m):
        for i in range (l):
            bucket[(arr[i][0])%10].append(arr[i])
        arr*=0 
        for i in range (10):
            while len(bucket[i]) > 0:
                arr.append(bucket[i].popleft())
                arr[-1][0] = arr[-1][0] // 10
    for i in range (l):
        arr[i] = a[arr[i][1]]
    return(arr)
