import sys
raw_input = iter(sys.stdin.read().splitlines()).next

def bfs(n):
    result, a = [], []
    q = [(n, 1)]
    while q:
        new_q = []
        for n, coeff in q:
            if n <= 2:
                for i in xrange(1, n+1):
                    a.append(i*coeff)
                continue
            pw = 1<<(n.bit_length()-1)
            if pw == n:
                a.append(n*coeff)
                n -= 1
                pw //= 2
            a.append(pw*coeff)
            for i in xrange(1, (n-pw)+1):
                result.append(((pw-i)*coeff, (pw+i)*coeff))
                a.append(2*pw*coeff)
            new_q.append((pw-(n-pw)-1, coeff))
            new_q.append((n-pw, 2*coeff))
        q = new_q
    return result, a

def solution():
    n = int(raw_input())
    if n == 2:
        return -1
    result, a = bfs(n)
    a.sort()
    expect_num = 1<<(n-1).bit_length()
    for i in xrange(len(a)-1):
        if a[i] != a[i+1]:
            continue
        result.append((a[i], a[i+1]))
        a[i+1] += a[i]
        a.remove(a[i])
        break
    for x in a:
        while x != expect_num:
            result.append((0, x))
            result.append((x, x))
            x *= 2
    result.append((0, expect_num))
    return "%s\n%s" % (len(result), "\n".join(map(lambda x: " ".join(map(str, x)), result)))

for case in xrange(int(raw_input())):
    print '%s' % solution()

import os
import sys
from io import BytesIO, IOBase

BUFSIZE = 8192

class FastIO(IOBase):
    newlines = 0

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count(b"\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines -= 1
        return self.buffer.readline()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0), self.buffer.seek(0)


class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode("ascii"))
        self.read = lambda: self.buffer.read().decode("ascii")
        self.readline = lambda: self.buffer.readline().decode("ascii")


sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)
