from collections import defaultdict as dd
from collections import deque
import bisect
import heapq

def ri():
    return int(input())

def rl():
    return list(map(int, input().split()))


def solve():
    n = ri()
    H = rl()
    G = dd(list)
    P = dd(lambda:-1)
    for i in range(n - 1):
        u, v = rl()
        u -= 1
        v -= 1
        G[u].append(v)
        G[v].append(u)

    root = 0
    highest = 0
    for i in range(n):
        if H[i] > highest:
            root = i
            highest = H[i]

    P[root] = root
    curr = [root]
    while curr:
        node = curr.pop()
        for nbr in G[node]:
            if P[nbr] == -1:
                P[nbr] = node
                curr.append(nbr)

    maxbelow = [0] * n
    # def dfs(u):
        # for v in G[u]:
            # if v != P[u]:
                # dfs(v)
                # maxbelow[u] = max(maxbelow[u], maxbelow[v], H[v])
# 
        # 
    # dfs(root)

    layers = [root]
    curr = [root]
    while curr:
        nxt = []
        for node in curr:
            for nbr in G[node]:
                if nbr != P[node]:
                    nxt.append(nbr)
        layers += nxt
        curr = nxt

    for u in layers[::-1]:
        for v in G[u]:
            if v != P[u]:
                maxbelow[u] = max(maxbelow[u], maxbelow[v], H[v])

    ans = 0
    for i in range(n):
        if i == root: continue
        ans += max(0, H[i] - maxbelow[i])

    paths = []
    for v in G[root]:
        paths.append(max(H[v], maxbelow[v]))
    if len(paths) == 1:
        ans += H[root] + H[root] - paths[0]
    else:
        paths.sort()
        ans += 2 * H[root] - paths[-1] - paths[-2]
    print (ans)



