class DisJoinUnion:
    def __init__(self,n):
        self.parent=list(range(n))
        self.rank=[1]*n

    def find(self,x):
        while x!=self.parent[x]:
            self.parent[x]=self.parent[self.parent[x]]
            x=self.parent[x]
        return x

    def union(self,x,y):
        fx,fy=self.find(x),self.find(y)
        if fx==fy:
            return

        self.parent[fy]=fx
        self.rank[fx]+=self.rank[fy]



