def hu(a,b,opp):
    d=1
    c=0
    while(0<b or 0<a):
        c=c+(((b%opp)+(a%opp))%opp)*d
        a=a//opp
        b=b//opp
        d=opp*d
    return c
def rw(u,opp):
    c=0
    d=1
    while(0<u):
        c=c+((-u%opp)%opp)*d
        u=u//opp
        d=opp*d
    return c
