def getInt():
    return int(input())


def getStr():
    return input().strip()


def getList(split=True):
    s = getStr()
    if split:
        s = s.split()
    return map(int, s)


# t = getInt()
t = 1


def p(*args, **kwargs):
    print(*args, **kwargs)
    stdout.flush()


def solve():
    n = getInt()
    e = [[0] * (n+1) for _ in range(n+1)]

    def ask(i):
        p("?", i)
        return list(getList())
    level = ask(1)

    def assign(i, a):
        for j, x in enumerate(a, 1):
            if x == 1:
                e[i][j] = e[j][i] = 1

    assign(1, level)
    l = max(level)
    color = [0, 0]
    for j in level:
        color[j & 1] += 1

    # color tree black and white, only query the color with the small nodes
    # which is <= n /2
    # we can color the graph by block and white nodes, odd level is black, even level is white
    # we notice that min(black, white) <= n / 2
    # hence we just need to query level of the min color
    who = color[1] < color[0]
    w = [[] for _ in range(l+1)]
    for i, j in enumerate(level, 1):
        w[j].append(i)
    for i in range(1, l+1):
        if i & 1 == who:
            for j in w[i]:
                assign(j, ask(j))

    p("!")
    for i in range(1, n+1):
        for j in range(1, i):
            if e[i][j]:
                p(i, j)


for _ in range(t):
    solve()

