def fun(a,n):
    if n == 1 or n == 2:
        return 0

    p = set()
    for i in range(1,n):
        p.add(a[i]-a[i-1])

    p = list(p)
    p.sort()

    if len(p) > 2:
        return -1
    elif len(p) == 2:
        m = p[1]+(abs(p[0]) if p[0]<0 else -p[0])
        c = p[1]
        if m <= max(a):
            return -1

        for i in range(1,n):
            if a[i] != (a[i-1]+c)%m:
                return -1        
        return m, c

    elif len(p) == 1:
        return 0    


