import os
import sys
from io import BytesIO, IOBase

BUFSIZE = 8192

class FastIO(IOBase):
    newlines = 0

    def __init__(self, file):
        self._fd = file.fileno()
        self.buffer = BytesIO()
        self.writable = "x" in file.mode or "r" not in file.mode
        self.write = self.buffer.write if self.writable else None

    def read(self):
        while True:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            if not b:
                break
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines = 0
        return self.buffer.read()

    def readline(self):
        while self.newlines == 0:
            b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
            self.newlines = b.count(b"\n") + (not b)
            ptr = self.buffer.tell()
            self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
        self.newlines -= 1
        return self.buffer.readline()

    def flush(self):
        if self.writable:
            os.write(self._fd, self.buffer.getvalue())
            self.buffer.truncate(0), self.buffer.seek(0)


class IOWrapper(IOBase):
    def __init__(self, file):
        self.buffer = FastIO(file)
        self.flush = self.buffer.flush
        self.writable = self.buffer.writable
        self.write = lambda s: self.buffer.write(s.encode("ascii"))
        self.read = lambda: self.buffer.read().decode("ascii")
        self.readline = lambda: self.buffer.readline().decode("ascii")


sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)
input = lambda: sys.stdin.readline().rstrip("\r\n")


class SegmentTree:
    def __init__(self, size):
        count = 1
        while count < size:
            count *= 2

        self.size = size
        self.count = count

        self.T = [0] * (count)
        self.V = [0] * (2*count)

    def __apply(self, e, v):
        if e < self.count:
            self.T[e] += v

        self.V[e] += v

    def __merge(vl, vr):
        return min(vl, vr)

    def __push(self, e):
        t = self.T[e]
        if t == 0:
            return

        self.__apply(2*e, t)
        self.__apply(2*e + 1, t)

        self.T[e] = 0

    def __updateCore(self, e, tl, tr, l, r, v):
        if r <= tl or tr <= l or l >= r:
            return

        if l <= tl and tr <= r:
            self.__apply(e, v)
        else:
            self.__push(e)

            tm = (tl + tr)//2
            self.__updateCore(2*e,     tl, tm,         l, min(tm, r), v)
            self.__updateCore(2*e + 1, tm, tr, max(l, tm),         r, v)

            self.V[e] = SegmentTree.__merge(self.V[2*e], self.V[2*e + 1])

    def update(self, l, r, v):
        self.__updateCore(1, 0, self.size, l, r + 1, v)

    def __queryCore(self, e, tl, tr, l, r):
        if r <= tl or tr <= l or l >= r:
            return 10**10

        if l <= tl and tr <= r:
            return self.V[e]
        else:
            self.__push(e)

            tm = (tl + tr)//2
            lv = self.__queryCore(2*e,     tl, tm,          l, min(tm, r))
            rv = self.__queryCore(2*e + 1, tm, tr, max(l, tm),         r)

            return SegmentTree.__merge(lv, rv)

    def query(self, l, r):
        return self.__queryCore(1, 0, self.size, l, r + 1)

    def clear(self, new = False):
        if new:
            self.T = [0] * self.count
            self.V = [0] * (2*self.count)
        else:
            for i in range(self.count):
                self.T[i] = self.V[i] = 0

            for i in range(self.count + 1, 2*self.count):
                self.V[i] = 0


