def solve(n,arr):

    if n == 1:
        return 0

    if arr[-1] == 0:
        return -1

    ans = 0
    for i in range(n-2,-1,-1):
        if arr[i] == 0 and i != 0:
            return -1
        while arr[i] != 0 and arr[i] >= arr[i+1]:
            arr[i] = arr[i] // 2
            ans += 1
        if arr[i] == 0 and i != 0:
            return -1

    return ans


