from random import seed, randint
import sys
raw_input = iter(sys.stdin.read().splitlines()).next

def f(a, w, vals):
    bits = [1<<randint(0, K-1) for _ in vals]
    masks = [reduce(lambda x, y: x|bits[y], row, 0) for row in a]
    dp = [float("inf")]*(1<<K)
    for i, x in enumerate(masks):
        dp[x] = min(dp[x], w[i])
    for mask in xrange(len(dp)):
        base = 1
        for i in xrange(K):
            dp[mask|base] = min(dp[mask|base], dp[mask])
            base <<= 1
    full_mask = len(dp)-1
    return min(x+dp[full_mask^masks[i]] for i, x in enumerate(w)) 

def solution():
    n, m = map(int, raw_input().strip().split())
    a, w = [None]*n, [0]*n
    for i in xrange(n):
        args = map(int, raw_input().strip().split())
        a[i], w[i] = args[:-1], args[-1]
    vals = set(a[i][j] for i in xrange(n) for j in xrange(m))
    lookup = {x:i for i, x in enumerate(vals)}
    for i in xrange(n):
        for j in xrange(m):
            a[i][j] = lookup[a[i][j]]
    result = min(f(a, w, vals) for _ in xrange(RETRY))
    return result if result != float("inf") else -1

