"""
// two can reach if y2-y1 <= x2-x1
// partition
// dilworth theorem , the smallest size of chain decompositions  of set A is equal to the size of the largest antiset. An antiset is a subset of  A such thta no two elemetn in the set is comparable.
// so two cany is incomparable if y2-y1 > x2-x1
// use triangle dp (imagine if rotate so the triable part become square)
"""

def solve():
  input()
  n , m = getList()
  dp = [[0] * (m+3) for _ in range(n+2)]

  for i in range(1, n+1):
      dp[i][1:1+m] = list(map(int, input().strip()))
  if n == 1:
    print(sum(dp[1]))
    return 
  res = [0,0]
  cnt = [0]

  def up(i,j):
    cnt[0] += 1
    if dp[i][j]:
      dp[i][j] = dp[i][j+2] + 1 
    else:
      dp[i][j] = max(dp[i-1][j+1], dp[i+1][j+1])
    res[(i^j)&1] = max(res[(i^j)&1], dp[i][j])

  for i in range(1,n+1):
    for k in range(min(i,m)):
      up(i-k,m-k) 

  for j in range(m-1,0,-1):
    for k in range(min(n,j)):
      up(n-k,j-k)
  # assert(cnt[0] == n * m)
  print(sum(res))








