    from collections import deque
    q=deque()
    for i,val in enumerate(in_degree):
        if(val==0):
            q.append(i)
    dp = [1 for i in range(n)]
    while(q):
        count+= 1
        temp = q.popleft()
        for item in adj[temp]:
            if(item<temp):
                if(dp[item]<dp[temp]+1):
                    dp[item] = dp[temp]+1
            else:
                if(dp[item]<dp[temp]):
                    dp[item]= dp[temp]
            in_degree[item]-=1
            if(in_degree[item]==0):
                q.append(item)
    if(count==n):
        print(max(dp))
    else:
        print(-1)

