def solve():
    n = int(input())
    s = input()
    P = list(map(int, input().split()))
    P = [x - 1 for x in P]

    seen = set()
    components = []

    def dfs(u, component):
        if u not in seen:
            seen.add(u)
            component.append(u)
            dfs(P[u], component)

    for i in range(n):
        if i not in seen:
            component = []
            dfs(i, component)
            components.append(component)

    def find_cycle_length(vals):
        a = ''.join(s[i] for i in vals)
        m = len(a)
        for k in range(1,m+1):
            if m % k != 0: continue
            if all(a[j] == a[j-k] for j in range(k,m)):
                return k
        assert False


    ans = [find_cycle_length(comp) for comp in components]
    return lcm(*ans)


