import math
def find_div(a,b,c,d):
    start = time()
    if a==b==1 or (c*d)/(a*b) == (c*d)//(a*b):
        return c, d
    if a*2<=c and b*2<=d:
        return 2*a, 2*b
    if c*d < 2*a*b:
        return -1,-1
    else: # executes if cd > 2ab
        s =[]
        if a<b:
            s.append(a)
            s.append(b)
        else:
            s.append(b)
            s.append(a)
        if c<1000 and d<1000:
            for x in range(a+1, c+1):
                for y in range(b+1, d+1):
                    if (x*y) % (a*b) == 0:
                        return x, y
        else:
            if a==1 and b==1:
                return 2, 2
            if a==1 and b<=c and b+1<=d:
                return b, b+1
            if b==1 and a<=d and a+1<=c:
                return a+1, a
            for i in range(2, (c*d)//(a*b)+1):
                if time() - start > 3.9:
                    return -1,-1
                if i*a*b <= c*d:
                    num = i*a*b
                    if a<b:    
                        for j in range(num//d, num//b+1):
                            if num % j == 0:
                                if b<num//j<=d and a<j<=c:
                                    return j, num//j
                    else:
                        for j in range(num//c, num//a+1):
                            if num % j == 0:
                                if a<num//j<=c and b<j<=d:
                                    return num//j, j
    return -1,-1

