def near(r, c, itself = False):
    if itself:
        yield (r, c)
    if 0 < r:
        yield (r - 1, c)
    if r + 1 < n:
        yield (r + 1, c)
    if 0 < c:
        yield (r, c - 1)
    if c + 1 < m:
        yield (r, c + 1)
