    v = A[x][y]
    if v == 1:
        return True

    return any(A[r][c] < v for r, c in near(x, y))


def swapAndCheck(r1, c1, r2, c2):
    if (r1 , c1) != (r2, c2):
        A[r1][c1], A[r2][c2] = A[r2][c2], A[r1][c1]

        flag = ok(r1, c1) and ok(r2, c2) and all(ok(r, c) for r, c in chain(near(r1, c1), near(r2, c2), H[1:]))

        A[r1][c1], A[r2][c2] = A[r2][c2], A[r1][c1]

        return flag

    return False


