def mcd(a,b):
 if a==0: return(b)
 if b==0: return(a)
 return mcd(b,a%b)



def solve(n,m,k,a,b):
 d = mcd(n,m)
 mcm = n*m//d
 [x,y] = BuscarIndices(n,m,d)

 collection = {}
 matchings = []

 for i in range(n):
  collection[a[i]] = i

 for j in range(m):
  if b[j] in collection and (collection[b[j]] - j) % d == 0:
   if m == 1:
    matchings += [collection[b[j]]]
   else:
    matchings+=[DevuelvePos(collection[b[j]],j,n,m,d,mcm,x,y)]

 matchings.sort()
 diasSinProcesar = k
 cantidadFinalDias = 0
 if k > mcm - len(matchings):
  cantidadFinalDias = ((k-1)//(mcm - len(matchings))) * mcm
  diasSinProcesar = (k-1)%(mcm - len(matchings)) + 1
 posicion_inicial = 0
 start,end = 0,len(matchings)-1

 while start<=end:
  med = (start+end)//2
  dias_rep = med - start
  total_dias_intervalo = matchings[med] - posicion_inicial
  dias_noRep = total_dias_intervalo - dias_rep
  if dias_noRep >= diasSinProcesar:
   end = med - 1
  else:
   cantidadFinalDias += total_dias_intervalo + 1
   diasSinProcesar -= dias_noRep
   posicion_inicial = matchings[med] + 1
   start = med + 1
 cantidadFinalDias += diasSinProcesar
 return cantidadFinalDias

def DevuelvePos(i,j,n,m,d,mcm,x,y):
 return ((i+j + (j-i)*(x*n + y*m)//d)//2)%mcm

def BuscarIndices(n,m,d):
 x,y=0,0
 for i in range(1, m):
  if (i * n - d) % m == 0:
   x = i
   y = (i * n - d) // m
   break
 return [x,y]




