                while x + 1 < n and y + 1 < m :
                    if a[x + 1][y + 1] == '*' :
                        countrightdown += 1
                        s = x + 1
                        t = y + 1
                        h = 1
                        while s - 1 >= 0 and t + 1 < m :
                            if a[s - 1][t + 1] == '*' :
