def dist(x1, x2, y1, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)


def mergeSort(arr, check = lambda a, b: a < b, reverse = False):
    if len(arr) > 1:

        # Finding the mid of the array
        mid = len(arr)//2

        # Dividing the array elements
        L = arr[:mid]

        # into 2 halves
        R = arr[mid:]

        # Sorting the first half
        mergeSort(L, check, reverse)

        # Sorting the second half
        mergeSort(R, check, reverse)

        i = j = k = 0

        # Copy data to temp arrays L[] and R[]
        while i < len(L) and j < len(R):
            if check(L[i], R[j]):
                if not reverse:
                    arr[k] = L[i]
                    i += 1
                else:
                    arr[k] = R[j]
                    j += 1
            else:
                if not reverse:
                    arr[k] = R[j]
                    j += 1
                else:
                    arr[k] = L[i]
                    i += 1 
            k += 1

        # Checking if any element was left
        while i < len(L):
            arr[k] = L[i]
            i += 1
            k += 1

        while j < len(R):
            arr[k] = R[j]
            j += 1
            k += 1


def maxSum(arr):

    max_sum = float('-inf')   
    max_cur = 0 
    for num in ar:
        max_cur = max(max_cur + num, num)
        if max_cur > max_sum:
            max_sum = max_cur
    return max_sum


def hcf(a, b):
    if b == 0:
        return a
    else:
        return hcf(b, b%a)


def get_power(n, m):
    i = 1
    p = -1
    while i <= n:
        i = i*m
        p += 1
    return p


