    else: return True


def upperbound(arr,val):
    start = 0; end = len(arr) - 1; ans = -1
    while (start <= end):
        mid = (start + end) // 2
        if (arr[mid] <= val):
            start = mid + 1
        else:
            ans = mid
            end = mid - 1
    return ans
def lowerbound(arr,val):
    length = len(arr); answer = -1; start = 0; end = length - 1    
    while start <= end:
        middle = (start + end)//2    
        if arr[middle] == val:
            answer = middle
            end = middle - 1
        elif arr[middle] > val:
            end = middle - 1    
        else:
            start = middle + 1
    return answer
def D2B(n):
    arr = []
    while (n > 0):
        temp = n; m = 0; p = 1
        while (temp):
            rem = temp % 10; temp = int(temp/10)
            if (rem != 0):
                m += p;
            p *= 10;
        arr.append(m); n = n - m;
    return arr
def sort2D(arr,axis):
    arr = sorted(arr, key = itemgetter(axis)); return arr
def DD(rows,cols):
    arr = [[0 for i in range(cols)] for j in range(rows)]; return arr
