def solve():
    n, q = read_int_tuple()
    A = read_int_list()

    pre = [0] * (n + 1)
    pxr = [0] * (n + 1)
    for i, x in enumerate(A, 1):
        pre[i] = x + pre[i - 1]
        pxr[i] = x ^ pxr[i - 1]
    idx = [i for i, x in enumerate(A) if x]

    for _ in range(q):
        L, R = read_int_tuple()
        li, ri = bisect_left(idx, L - 1), bisect_right(idx, R - 1) - 1
        if not (0 <= li <= ri < len(idx)):
            print(L, L)
            continue

        L, R = idx[li], idx[ri]
        tx = pxr[R + 1] ^ pxr[L]
        hi = pre[R + 1] - pre[L] - tx
        if hi == 0:
            print(L + 1, L + 1)
