def coords(n, u):
    level = 0
    while (u & 1) == 0:
        u >>= 1
        level += 1
    return level, (u - 1) / 2

def uncoords(n, level, idx):
    return (1 << level) * (2 * idx + 1)

def get_up(n, u):
    level, idx = coords(n, u)
    # already at root
    if u == (n + 1) / 2:
        return u
    new_level = level + 1
    new_idx = idx / 2
    return uncoords(n, new_level, new_idx)

def get_left(n, u):
    level, idx = coords(n, u)
    # already at leaf
    if level == 0:
        return u
    new_level = level - 1
    new_idx = idx * 2
    return uncoords(n, new_level, new_idx)

def get_right(n, u):
    level, idx = coords(n, u)
    # already at leaf
    if level == 0:
        return u
    new_level = level - 1
    new_idx = idx * 2 + 1
    return uncoords(n, new_level, new_idx)

