M=2*10**5+10
def to(x):
    num2,num,cnt1=x
    return [num2,num*M+cnt1]
def inv(x):
    num2=x[0]
    y=x[1]
    cnt1=y%M
    num=y//M
    return [num2,num,cnt1]


def op(a,b):
    a=inv(a)
    b=inv(b)
    res=[0,0,0]
    res[0]=a[0]+b[0]
    res[1]=a[1]+b[1]
    res[2]=a[2]+b[2]
    return to(res)

def mapping(f,x):
    x=inv(x)
    num2,num,cnt1=x
    res2,res,rescnt1=0,0,0
    res2=num2+2*f*num+f**2*cnt1
    res=num+f*cnt1
    rescnt1=cnt1
    return to([res2,res,rescnt1])
def compose(f,g):
    return f+g






