class BIT:
    #https://atcoder.jp/contests/abc233/submissions/28159326
    def __init__(self,arg):

        if isinstance(arg,int):
            self.N=arg
            self.dat=[0]*(self.N+1)
        else:
            self.N=len(arg)
            self.dat=[0]+list(arg)
            for i in range(self.N.bit_length()-1):
                for j in range(self.N>>(i+1)):
                    idx=(j<<1|1)<<i

                    nidx=idx+(idx&-idx)
                    if nidx<self.N+1:
                        self.dat[nidx]+=self.dat[idx]


    def add(self,idx,x):
        idx+=1
        while idx<self.N+1:
            self.dat[idx]+=x

            idx+=idx&-idx

    def sum(self,idx):
        if idx<0:return 0
        idx+=1
        sum_=0
        while idx>0:
            sum_+=self.dat[idx]

            idx-=idx&-idx
        return sum_

    def query(self,l,r):
        if l>=r:return 0
        return self.sum(r-1)-self.sum(l-1)

    def get(self,k):
        return self.query(k,k+1)

    def update(self,k,x):
        self.add(k,-self.get(k))
        self.add(k,x)

    def lower_bound(self,x):
        sum_=0
        idx=1<<(self.N.bit_length()-1)
        while True:
            if idx<self.N+1 and sum_+self.dat[idx]<x:
                sum_+=self.dat[idx]
                if idx&-idx==1:
                    break
                idx+=(idx&-idx)>>1
            else:
                if idx&-idx==1:
                    idx-=1
                    break
                idx-=(idx&-idx)>>1
        return idx,sum_

