def armor_and_weapons(n, m, combos):
    current_wave = [(1, 1, 0)]

    while len(current_wave) > 0:
        next_wave = []
        max_x = 0

        current_wave.sort(key=lambda x: (-x[1], -x[0]))
        for x, y, hours in current_wave:
            if x > max_x:
                max_x = x
                power = x + y
                if (x, y) in combos:
                    power += 1

                if x != n:
                    new_x = min(power, n)

                    next_wave += [(new_x, y, hours + 1)]
                elif power >= m:
                    return hours + 1

                if y != m:
                    new_y = min(power, m)

                    next_wave += [(x, new_y, hours + 1)]
                elif power >= n:
                    return hours + 1

        current_wave = next_wave


