def binom(n,k):
  if n<0 or k<0:
    return 0
  if k>n:
    return 0
  return (fac[n]*finv[k]%mod)*finv[n-k]%mod

def conv(a,b):
  na=len(a)
  nb=len(b)
  c=[0]*(na+nb-1)
  for i in range(na):
    for j in range(nb):
      c[i+j]=(c[i+j]+a[i]*b[j])%mod
  return c

