def process(n, k, a):
    counts = {}
    indices = {}

    for i in range(len(a)):
        if a[i] in counts:
            counts[a[i]]+=1
        else:
            counts[a[i]]=1 
        if a[i] in indices:
            indices[a[i]].append(i)
        else:
            indices[a[i]]=[i]

    counter = 0 

    to_sort =[]

    for i in counts: 
        counter+=min(counts[i], k)
        to_sort.append((i, min(counts[i], k)))


    to_sort.sort(key = lambda x: x[1], reverse = True)

    #print(to_sort)

    to_return = [0]*n 
    paint_number = 0 

    paint_max = int(counter/k)*k

    for i, j in to_sort:

        painted = 0 


        while(painted<j ):
            if paint_number == paint_max: return to_return
            to_return[indices[i][painted]]=(paint_number%k)+1
            paint_number+=1
            painted+=1



    return to_return



