def sqrt(x):
	low , high = 0 , x
	while low <= high:
		mid = (low + high) // 2
		if mid * mid <= x < (mid+1) * (mid+1):
			return mid
		elif x < mid * mid:
			high = mid - 1
		else:
			low = mid + 1



