from types import GeneratorType
def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        else:
            to = f(*args, **kwargs)
            while True:
                if type(to) is GeneratorType:
                    stack.append(to)
                    to = next(to)
                else:
                    stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(to)
            return to
    return wrappedfunc

@bootstrap
def fun(adj,v,p,rem):
    ans=0
    f=0
    nf=0
    for i in adj[v]:
        if i==p:
            continue
        (cans,cf) = yield fun(adj,i,v,rem)
        if cf==0:
            nf+=1
            rem.add((v,i))
            ans+=1
        else:
            f+=1
            if f>2:
                ans+=1
                rem.add((v,i))
        ans += cans

    if f<2:
        yield (ans,1)
    else:
        yield (ans,0)

def get(parent,a):
    if parent[a]==a:
        return a
    return get(parent,parent[a])

def merge(parent,a,b):
    a = get(parent,a)
    b = get(parent,b)
    if a>b:
        a,b = b,a
    parent[b]=a
    return

