def accordian(s):
    idx1=s.find("[")
    if idx1==-1:
        return("-1")
    s=s[idx1+1:]

    idx2=s.find(":")
    if idx2==-1:
        return("-1")
    s=s[idx2+1:]

    s=s[::-1]

    idx3=s.find("]")
    if idx3==-1:
        return("-1")
    s=s[idx3+1:]

    idx4=s.find(":")
    if idx4==-1:
        return("-1")
    s=s[idx4+1:]

    count=s.count("|")
    count+=4
    return count
