def alternating_sum(n, a):    
    alter_sum = 0
    for i in range(n):
        if i % 2 != 0:
            alter_sum -= a[i]
        else:
            alter_sum += a[i]
    return alter_sum

def zero_partition(n, a):
    if n % 2 != 0:
        return -1

    if alternating_sum(n, a) == 0:
        return [[1, n]]

    segments = []
    for i in range(0, n, 2):
        if a[i] == a[i+1]:
            segments.append([i+1, i+2])
        else:
            segments.append([i+1, i+1])
            segments.append([i+2, i+2])
    return segments

