mod=998244353

def ans(A):
    LEN=len(A)
    ANS=0

    for i in range(1<<LEN):
        X=[0]*LEN
        for j in range(LEN):
            if i & (1<<j) != 0:
                X[j]=1

        C=[]
        P=[]
        SC=0
        SP=0
        for i in range(LEN):
            if X[i]==1:
                C.append(i)
                SC+=A[i]
            else:
                P.append(i)
                SP+=A[i]

        if SC>=SP:
            continue

        flag=1
        for i in range(2,len(C)):
            if C[i-1]-C[i-2]>C[i]-C[i-1]:
                flag=0
                break

        for i in range(2,len(P)):
            if P[i-1]-P[i-2]<P[i]-P[i-1]:
                flag=0
                break

        if flag==0:
            continue
        else:
            ANS+=1
    return ANS%mod


