        ways.append( 2 * horizontal[i][j-1] + grid[i][j-1])
    if m-1-j:
        ways.append(2 * horizontal[i][j] + grid[i][j+1])
    if i:
        ways.append(2 * vertical[i-1][j] + grid[i-1][j])
    if n-1-i:
        ways.append(2 * vertical[i][j] + grid[i+1][j])
    return min(ways)

