class Point:
	def __init__(self, x, y):
		self.x = x
		self.y = y

	def __str__(self):
		return str([self.x, self.y])

def neighbours(res, p):
	n = []
	if p.y - 1 >= 0:
		n.append(Point(p.x, p.y-1))
	if p.x + 1 < len(res):
		n.append(Point(p.x+1, p.y))
	return n
def calc(diag, x, left, res, p):
	# print("point", p, "value", diag[x])
	if x == len(diag):
		return True
	if left == 0:
		return True
	ns = neighbours(res, p)
	# print("neighbours", *ns)
	for n in ns:
		if res[n.x][n.y] == None:
			res[n.x][n.y] = res[p.x][p.y]
			return calc(diag, x, left-1, res, n)
	return False

