def sieve(n):
    prime = [True]*(n+1)
    p = 2
    a=[]
    for p in range(2,int(n**0.5)+1):
        if (prime[p] == True):
            a.append(p)
            for l1 in range(p * p, n+1, p):
                prime[l1] = False
    return a
def simplesieve(n):
    prime=[2]
    mark=[False]*(n+1)
    for p in range(3,n+1,2):
        if(mark[p]==False):
            prime.append(p)
            if(p*p<=n):
                for l1 in range(p*p,n +1,2*p):
                    mark[l1]=True
    return prime
def segementedsieve(low,high):
    primes=simplesieve(int(high**0.5))
    prime = [True] * (high-low + 1)
    for l1 in primes:
        lower = (low//l1)
        if lower <= 1:
            lower = l1+l1
        elif (low % l1) != 0:
            lower = (lower * l1) + l1
        else:
            lower = lower*l1
        for l2 in range(lower, high+1, l1):
            prime[l2-low] = False
    a=[]
    s=0
    for l in range(low, high + 1):
        if prime[l-low]:
            a.append(l)
    return a
def isprime(n):
    if(n==2):
        return True
    if(n%2==0 or n==1):
        return False
    for l1 in range(3,int(n**0.5)+1,2):
        if(n%l1==0):
            return False
    return True
