def binsearch(a,l,r,key):
    while(r-l>1):
        m=l+(r-l)//2
        if(a[m]<=key):
            l=m
        else:
            r=m
    if(a[l]==key):
        return l
    if(a[r]==key):
        return r
    return -1
class Node():
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
def inorder(root):
    res, stack = [], []
    current = root
    while True:
        while current:
            stack.append(current)
            current = current.left
        if len(stack) == 0:
            return res
        node = stack[-1]
        stack.pop(len(stack)-1)
        if node.data != None:
            res.append(node.data)
        current = node.right
    return res 

