    G = defaultdict(list)
    edges_back = {}
    colors = [0] * m
    for k in range(m):
        a, b, c = [int(i) for i in input().split()]
        G[a] += [(b, c)]
        G[b] += [(a, c)]
        edges_back[(a, b)] = (k, c)
        edges_back[(b, a)] = (k, c)
        colors[k] = c

    ans = set()
    for n1 in range(1, n + 1):
        neibs = G[n1]
        for (n2, c12), (n3, c13) in combinations(neibs, 2):
            if (n2, n3) in edges_back:
                row = [[0] * U, [0] * U]
                k12, _ = edges_back[(n1, n2)]
                k13, _ = edges_back[(n1, n3)]
                k23, c23 = edges_back[(n2, n3)]
                last = 0
                for k, c in (k12, c12), (k13, c13), (k23, c23):
                    if c != -1:
                        last -= c
                    else:
                        flip_bit(row[0], k)
                last %= 3
                if last == 1:
                    flip_bit(row[0], m)
                elif last == 2:
                    flip_bit(row[0], m)
                    flip_bit(row[1], m)

                ans.add(tuple(tuple(x) for x in row))

    mat1, mat2 = [], []
    for x, y in ans:
        mat1 += [list(x)]
        mat2 += [list(y)]

    ans = Gauss(mat1, mat2, len(mat1), m)

    if ans[0] == 0:
        out = [-1]
    else:
        out = []
        for i in range(m):
            if colors[i] != -1:
                out += [colors[i]]
            elif ans[1][i] == 0:
                out += [3]
            else:
                out += [ans[1][i]]

    print(" ".join(str(x) for x in out))

