def transform(a):
    f={}
    for i in a:
        if i not in f:
            f[i]=1
        else:
            f[i]+=1
    b=[]
    for i in f:
        b+=[f[i]]
    m=max(b)
    ff=[0 for i in range(m+1)]
    present=[False for i in range(m+1)]
    for i in b:
        ff[i]+=1
        present[i]=True
    present=[i for i,j in enumerate(present) if j]
    return ff,present

def solve(ff,present):
    x=len(ff)-1
    z=len(present)-2
    flag=True
    if z>=0:
        y=present[z]
    else: 
        flag=False
    while x and flag and y>0:
        #print(ff,x,y)
        if y==0:
            break
        if ff[x]>1:

            ff[y]+=ff[x]-ff[x]%2
            ff[x]=ff[x]%2
            x+=ff[x]%2


        else:
            ff[x]=0
            ff[x-1]+=1
            ff[y]-=1
            ff[y-1]+=1
        if ff[x-1]>0:
            x=x-1
        else:
            x=y
        if x==y or ff[y]==0:
            if ff[y-1]>0 or y==1:
                y=y-1
            else:
                z-=1
