def solve():
	h, w = map(int, input().split())
	# if h > w:
	# 	h, w = w, h

	result = str()
	void_str = ("0" * w) + "\n"

	top_str = "10" * (w // 2)
	if w % 2 == 1:
		top_str += "1"

	top_str += "\n"

	if h % 2 == 0:
		bottom_str = "0" * w
	else:
		bottom_str = "10" * (w // 2)
		if w % 2 == 1:
			bottom_str += "1"

	bottom_str += "\n"

	middle_str = "1" + ("0" * (w - 2)) + "1\n"

	result += top_str

	if h % 2 == 0:
		for i in range(2, h - 1):
			if i % 2 == 0:
				result += void_str
			else:
				result += middle_str

		result += void_str
		result += top_str

	else:
		for i in range(2, h):
			if i % 2 == 0:
				result += void_str
			else:
				result += middle_str

		result += bottom_str

	print(result.strip())

