from collections import defaultdict

def first(U):
    if len(U) == 0:
        return None

    it = iter(U)
    return next(it)

def solve(A):
    N = len(A)

    for i in range(N):
        A[i] -= 1

    r = 0
    B = [None] * N
    U = {}
    empty = []
    for i in range(N):
        if A[i] not in U:
            B[i] = A[i]
            U[A[i]] = i
            r += 1
        else:
            empty.append(i)

    if len(empty) == 1:
        e = empty[0]
        if e not in U:
            B[e] = A[e]
            B[U[A[e]]] = e
        else:
            for z in range(N):
                if z not in U:
                    B[e] = z
                    break
    elif len(empty) > 1:
        src = empty
        src.sort(lambda x: 0 if x not in U else 1)

        dst = []
        G = {i for i in range(N) if i not in U}
        for s in src:
            if s not in U:
                dst.append(s)
                G.discard(s)
        dst.extend(G)

        size = len(src)
        for i in range(size):
            B[src[i]] = dst[(i + 1) % size]


    print(r)
    print(" ".join(str(e + 1) for e in B))

