def solve():
    n, k = list(map(int, input().split()))
    arr = list(map(int, input().split()))
    if n == k:
        print(10 ** 9)
        return
    new_arr = []
    for i in range(n):
        new_arr.append((arr[i], i))
    new_arr.sort()
    i = 0
    k -= 1
    while k:
        arr[new_arr[i][1]] = 10 ** 9
        i += 1
        k -= 1

    min_idx = set([0])
    curr = arr[0]
    l = 0
    for i in range(1, n):
        l = max(l, min(arr[i-1], arr[i]))
        temp = arr[i]
        if temp < curr:
            min_idx = set([i])
            curr = temp
        elif temp == curr:
            min_idx.add(i)

    edge = curr
    if len(min_idx) == 1:
        sub_min = math.inf
        for i in range(n):
            if i not in min_idx:
                sub_min = min(sub_min, arr[i])

    if arr[0] < arr[1]:
        e = edge
        if 0 in min_idx and len(min_idx) == 1:
                e = sub_min
        ans = min(max(l, arr[1]), 2 * e)
    else:
        ans = min(l, 2 * edge)

    for i in range(1, n - 1):
        if arr[i] < arr[i-1] or arr[i] < arr[i+1]:
            e = edge
            if i in min_idx and len(min_idx) == 1:
                e = sub_min
            ans = max(ans, min(max(l, arr[i-1], arr[i+1]), 2 * e))

    if arr[n-1] < arr[n-2]:
        e = edge
        if n - 1 in min_idx and len(min_idx) == 1:
            e = sub_min
