def match_seq(power_2, s):

	i = j = 0
	while i < len(power_2) and j < len(s):
		if power_2[i] == s[j]:
			i += 1
			j += 1
		else:
			j += 1

	deleted_char = len(s) - i
	to_add = len(power_2) - i
	return deleted_char + to_add




