for _ in range(int(input())):
    n, k = inp(int)
    a = array('i', sorted(inp(int)))
    coun = segmenttree(n + 2)
    coun2 = segmenttree(n + 2)
    ix, ans = n - 1, n
    cum = array('i', [0] * (n + 3))

    for i in range(n):
        if a[i] <= n:
            cum[a[i]] = 1

    for i in range(1, n + 1):
        cum[i] += cum[i - 1]

    for mex in range(n, -1, -1):
        mmex = 0

        while ix > -1 and a[ix] >= mex:
            mmex += 1
            if ix == 0 or a[ix] != a[ix - 1]:
                coun[mmex] += mmex
                coun2[mmex] += 1
                mmex = 0

            ix -= 1

        if ix < n - 1 and a[ix + 1] != mex:
            mmex = 0

        k_ = k - mmex
        rem = max(mex - cum[mex - 1] - mmex, 0)

        if rem > k_:
            continue

        coun2[mmex] -= 1
        coun[mmex] -= mmex
        if coun.query(1, n + 1) <= rem:
            ans = 0
        else:
            be, en = 0, n
            while be < en:
                md = (be + en + 1) >> 1
                if coun.query(0, md + 1) <= k_:
                    be = md
                else:
                    en = md - 1

            k_ -= coun.query(1, be + 1)
            ans = min(ans, coun2.query(1, n + 1) - (coun2.query(1, be + 1) + k_ // (be + 1)))

        coun2[mmex] += 1
        coun[mmex] += mmex
    out.append(f'{ans}')
print('\n'.join(out))

