def calc(numOne, numTwo):

    currentSum = 0
    for i in range(32):
        firstBit, secondBit = min(1, numOne & (1 << i)), min(1, numTwo & (1 << i))

        currentSum += (firstBit ^ secondBit)

    return currentSum    


