from sys import stdin, stdout
from types import GeneratorType


def bootstrap(f, stack=[]):
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        to = f(*args, **kwargs)
        while True:
            if type(to) is GeneratorType:
                stack.append(to)
                to = next(to)
            else:
                stack.pop()
                if not stack:
                    break
                to = stack[-1].send(to)
        return to

    return wrappedfunc


def readint():
    return int(stdin.readline())

def readarray(typ):
    return list(map(typ, stdin.readline().split()))

def print_list(l):
    print(' '.join(list(map(str, l))))

ans = 0

@bootstrap
def dfs(u, adj, ss, ks, cum_scores):
    global ans
    k = ks[u]
    nn = len(adj[u])

    ans += ss[u] * k

    if nn == 0: # leaf
        cum_scores[u] = ss[u]
        yield cum_scores[u]

    scores = []
    ks_ = [k // nn for _ in range(nn)]

    for v, k_ in zip(adj[u], ks_):
        ks[v] = k_
        score = yield dfs(v, adj, ss, ks, cum_scores)
        scores.append(score)

    vals = sorted(scores, reverse=True)
    for val in vals[:k % nn]:
        ans += val

    cum_scores[u] = ss[u] + vals[k % nn]
    yield cum_scores[u]



