from functools import cache

@cache
def solveu(p, q):
    if p + q <= 2:
        return 0

    if p == 2 and q == 1:
        return 2

    if p + q < 10:
        uu, vv = solved(p, q, 0)

        pl = uu
        ql = vv

        pr = p - pl
        qr = q - ql
    else:
        pl = p // 2
        pr = p - pl

        qr = q // 2
        ql = q - qr

    #print(pl, pr, ql, qr)

    return 1 + max(solveu(pl + ql, pr), solveu(pr + qr, pl))

@cache
def solve(p, q):
    if p + q <= 2:
        return 0

    if p == 2 and q == 1:
        return 2

    pl = p // 2
    pr = p - pl

    qr = q // 2
    ql = q - qr

    #print(pl, pr, ql, qr)

    return 1 + max(solve(pl + ql, pr), solve(pr + qr, pl))

@cache
def solved(p, q, d):
    if d > 100:
        return d

    if p + q <= 2:
        return d

    if p == 2 and q == 1:
        return 2 + d

    poss = []

    for i in range(p + 1):
        for j in range(q + 1):
            poss.append((max(solved(i + j, p - i, d + 1), solved(p - i + q - j, i, d + 1)), i, j))

    if d == 0:
        return min(poss)[1:]

    return min(poss)[0]

