            cc, rr = sumc[idx][pp]-sumc[idx][last], sumr[idx][pp]-sumr[idx][last]
            # print(mid, th, h, last, pos, sr, sc, cc, rr, cc+sc + point*(sumr0[mid]-sr-rr), d1)
