memo = {}
def get_divisors(x: int) -> list:
    if x in memo:
        return memo[x]

    factori = []
    while x > 1:
        factori.append(min_fact[x])
        x //= min_fact[x]

    now = [1]
    factori.sort()
    for p in factori:
        nxt = []
        for i in now:
            nxt.append(i*p)
            if i % p:
                nxt.append(i)
        now = nxt
    memo[x] = now
    return now


def sieve_of_eratosthenes(n):
    min_fact = [1] * (n + 1)

    lst = [1] * (n+1)

    for p in range(2, n + 1):
        if min_fact[p] > 1:
            continue
        for i in range(p, n+1, p):
            min_fact[i] = p
            lst[i] *= 2

    return min_fact, lst


