    a = list(map(int, input().split()))
    a.sort()
    h = Counter(a)
    ans = (-inf, -1, -1)
    left = 0
    for right in range(n):
        if h[a[right]] < k:
            left = right + 1
            continue
        if right != 0 and a[right]-a[right-1] > 1 and right != left:
            left = right
            continue
        if a[right] - a[left] > ans[0]:
            ans = (a[right] - a[left], a[left], a[right])

    if ans[0]==-inf:
        print(-1)
    else:
        print(f"{ans[1]} {ans[2]}")






