counter = 0
def bootstrap(f, stack=[]):
    from types import GeneratorType
    def wrappedfunc(*args, **kwargs):
        if stack:
            return f(*args, **kwargs)
        else:
            to = f(*args, **kwargs)
            while True:
                if type(to) is GeneratorType:
                    stack.append(to)
                    to = next(to)
                else:
                    stack.pop()
                    if not stack:
                        break
                    to = stack[-1].send(to)
            return to

    return wrappedfunc


@bootstrap
def DFS(node, prev, graph, arr, dp, val):
  global counter
  next = graph[node]

  c = 0

  for i in next:

    if i != prev:

      yield DFS(i, node, graph, arr, dp, val)
      c += 1

      if dp[i] == val:
        counter += 1

      else:
        dp[node] = dp[node] ^ dp[i]


  dp[node] = dp[node] ^ arr[node]
  yield


