def solve(n, aa):
    head, tail = [], []
    if n % 2 == 1:
        a, b, c = aa[n-3], aa[n-2], aa[n-1]
        if b + c != 0:
            tail = [b+c, -a, -a]
        else:
            tail = [b-c, -a, a]
        n -= 3

    idx = 0
    while idx < n:
        factor = gcd(aa[idx], aa[idx+1])
        head.append(aa[idx+1] // factor)
        head.append(-aa[idx] // factor)
        idx += 2
    return head + tail


def gcd(x, y):
    x, y = abs(x), abs(y)
    while y:
        x, y = y, x % y
    return x


