def open_doors(input):
    """ 
        Primero dividir el string que llega, iterarlo 
        y si detecta las keys, la primera letra mayuscula 
        debe poder abrirse si tenemos las llaves
    """
    doors = ['R', 'G', 'B']
    keys = []

    characters = list(input)
    for character in characters:
        if character.isupper() and character == characters[0]:
            print("NO")
            break
        if character.islower():
            keys.append(character)
        elif character.isupper() and character in doors:
            lower = character.lower()
            if lower in keys:
                doors.remove(character)
                keys.remove(lower)
            else:
                print("NO")
                break
        if doors == []:
            print("YES")
            break

