import collections

def solve(As, Bs, Ms):
    # collect dishes with same (a + b - m) as groups
    groups = collections.defaultdict(list)
    for i, (a, b, m) in enumerate(zip(As, Bs, Ms)):
        groups[a + b - m].append((a + min(b - m, 0), max(a - m, 0), i))

    var = 0
    ans = [None for _ in range(len(As))]
    for (_, group) in groups.items():
        group.sort()  # sort (max_a, min_a, i)
        prev_a = -1
        for (max_a, min_a, idx) in group:
            if min_a <= prev_a:
                ans[idx] = [(As[idx] - prev_a), (Ms[idx] - (As[idx] - prev_a))]
            else:
                ans[idx] = [(As[idx] - max_a), (Ms[idx] - (As[idx] - max_a))]
                prev_a = max_a
                var += 1
    print(var)
    for a in ans:
        print(*a)

def main():
    Q = int(input())
    for _ in range(Q):
        input()
        n = int(input())
        As, Bs, Ms = [], [], []
        for _ in range(n):
            a, b, m = map(int, input().split())
            As.append(a); Bs.append(b); Ms.append(m)
        solve(As, Bs, Ms)

