def helper2(arr, f, curr):
    if f % 2:
        vals2 = arr[0][f:]
        vals2 = vals2[::-1]
        vals = arr[1][f + 1:] + vals2
    else:
        vals2 = arr[1][f:]
        vals2 = vals2[::-1]
        vals = arr[0][f + 1:] + vals2

    update = False
    for i in range(len(vals)):
        if curr < vals[i]:
            update = True
        curr = max(curr, vals[i]) + 1
    return update, curr


def helper(idx, arr, greedy):
    f = idx[0]
    curr = greedy[f]
    update, curr = helper2(arr, f, curr)
    if not update:
        return curr
    else:
        lo, hi = 0, len(idx)-1
        while lo < hi:
            mid = (lo + hi + 1)//2
            curr = greedy[idx[mid]]
            f = idx[mid]
            update, curr = helper2(arr, f, curr)
            if update:
                lo = mid
            else:
                hi = mid - 1

        f = idx[lo]
        curr = greedy[f]
        update, curr = helper2(arr, f, curr)
        if f + 1 < len(greedy):
            f2 = f + 1
            curr2 = greedy[f2]
            update, curr2 = helper2(arr, f2, curr2)
        else:
            curr2 = curr
        return min(curr, curr2)


def solve():
    m = int(input())
    arr = [list(map(int, input().split())) for _ in range(2)]
    greedy = [0]*m
    even, odd = [], []
    for i in range(m-1):
        if i % 2:
            greedy[i+1] = max(max(arr[0][i] + 1, greedy[i]+1) + 1, arr[0][i+1] + 1)
            odd.append(i)
        else:
            greedy[i+1] = max(max(arr[1][i] + 1, greedy[i]+1) + 1, arr[1][i+1] + 1)
            even.append(i)
    if (m-1) % 2:
        odd.append(m-1)
    else:
        even.append(m-1)
    return min(helper(even, arr, greedy), helper(odd, arr, greedy))


for _ in range(int(input())):
    print(solve())

