def knights(ro, co):
	if ro == 1 or co == 1:
		return (ro,co)

	directions = [(-2,1),(-2,-1),(2,1),(2,-1),(-1,-2),(1,-2),(-1,2),(1,2)]

	for row in range(1, ro+1):
		for column in range(1, co+1):
			isImmobile = True
			for move in directions:
				if ((row+move[0]) >= 1  and (row+move[0]) <= ro) and ((column+move[1]) >= 1  and (column+move[1]) <= co):
					isImmobile = False

			if isImmobile:
				return (row,column)

	return (ro,co)

