def check(stack):

    return (all(i < j for i, j in zip(stack, stack[1:])))


def greedy(stack,i,j):
    if stack[i] == 0 or stack[i] < i:
        return stack
    temp  = stack[i] - i
    stack[i] -= temp
    stack[j] += temp
    return stack
