def check(median):
    mini = 2*10**5+1
    part_sums = [0]
    for val in a[:k]:
        part_sums.append(part_sums[-1] + (val >= median) - (val < median))
    for key, val in enumerate(a[k:]):
        mini = min(mini, part_sums[key])
        if part_sums[-1] - mini > 0:
            return True
        part_sums.append(part_sums[-1] + (val >= median) - (val < median))
    # corner n == k
    mini = min(mini, part_sums[n - k])
    if part_sums[-1] - mini > 0:
        return True
    return False


def search(l, r) -> int:
    if l == r - 1:
        return l
    mid = (l + r) // 2
    if check(mid):
        return search(mid, r)
    return search(l, mid)


