class DSU:
    def __init__(self, limit):
        self.link = [-1]*limit
        self.sz = [1]*limit
        self.even = [False] * limit

    def find(self,u):
        root = u
        par = u
        while par != -1:
            root = par
            par = self.link[par]

        par = u
        while par != root:
            self.link[par] = root
            par = self.link[par]

        return root

    ''' return True if u and v were not in same group, false otherwise '''
    def union(self,u,v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u == root_v:
            return False
        rank_u = self.sz[root_u]
        rank_v = self.sz[root_v]
        if rank_u < rank_v:
            self.link[root_u] = root_v
            self.sz[root_v] += self.sz[root_u]
        else:
            self.link[root_v] = root_u
            self.sz[root_u] += self.sz[root_v]
        return True

    ''' return size of the component containing u '''
    def size(self,u):
        return self.sz[self.find(u)]

def solve():

    dsu_zero = [DSU(N) for _ in range(30)]
    dsu_one = [DSU(N) for _ in range(30)]

    for j in range(30):
        zero = dsu_zero[j]
        one = dsu_one[j]
        for u,v,w in E:
            if w >> j & 1:
                zero.union(u,v)
                if j > 0 and w & 1:
                    one.union(u,v)

    even = [False] * N
    for u,v,w in E:
        if not w & 1:
            even[u] = True
            even[v] = True

    link = [False] * N
    for j in range(1,30):
        dsu = dsu_one[j]
        for u,v,w in E:
            if not w & 1:
                root_u = dsu.find(u)
                dsu.even[root_u] = True
                root_v = dsu.find(v)
                dsu.even[root_v] = True

    for j in range(1,30):
        dsu = dsu_one[j]
        for n in range(N):
            if not link[n] and dsu.even[dsu.find(n)]:
                link[n] = True

    def mex(u,v):
        for j in range(30):
            dsu = dsu_zero[j]
            if dsu.find(u) == dsu.find(v):
                return 0
        if link[u]:
            return 1
        if even[u]:
            return 1
        return 2

    res = []
    for u,v in Q:
        res.append(mex(u,v))

    return "\n".join(str(v) for v in res)

for test in range(1,1+1):
