from functools import lru_cache
@lru_cache(maxsize=None)
def is_prime(a):
	if a==1:return False
	for i in range(2,int(a**0.5)+1):
		if a%i==0:
			return False
	return True

def cal(B):
	ans = 0
	for i,b in enumerate(B):
		if b==2:
			l,r = i,i
			for j in range(i-1,-1,-1):
				if B[j]==1:
					l=j
				else:
					break
			for j in range(i+1,len(B)):
				if B[j]==1:
					r=j
				else:
					break
			ans += (r-i)+(i-l)+(r-i)*(i-l)
	return ans

for _ in range(int(input())):
	N,E = map(int, input().split())
	A = list(map(int, input().split()))
	B = [[] for _ in range(E)]
	for i in range(E):
		for j in range(i,N,E):
			B[i].append(A[j])

	ans = 0
	for b in B:
		for i,d in enumerate(b):
			if d==1:continue
			if is_prime(d):
				b[i] = 2
			else:
				b[i] = 0
		ans += cal(b)
	print(ans)

