    maxi=a0
    sum=a0
    for i in range(N):
        var1=a0+x
        var2=a0-y
        if var1<=B:
            maxi=var1
            if var2<=B and var2>=var1:
                maxi=var2
        else:
            if var2<=B:
                maxi=var2

        a1=maxi
        sum+=maxi
        a0=a1
    print(sum)

