def type_(list_v, group):
    cnt_0 = 0
    cnt_1 = 0

    for v in list_v:
        if v in group:
            cnt_1 += 1
        else:
            cnt_0 += 1

    if cnt_1 == len(group):
        return 1

    if cnt_0 == len(list_v):
        return 0

    return 2

