def judge(last,key,d1,d2):
    if key>last:
        for (a,b,c) in data:
            if last<c<=key:
                d1[a].add(b)
                d2[b].add(a)

    else:
        for (a,b,c) in data:
            if key<c<=last:
                d1[a].remove(b)
                if not d1[a]:
                    del d1[a]
                d2[b].remove(a)
                if not d2[b]:
                    del d2[b]
    if len(d1.keys())<n or len(d2.keys())<n:
        return False

    for a in d1:
        lone = 0
        for b in d1[a]:
            if len(d2[b])==1:
                lone+=1
                if lone>1:
                    return False
    for b in d2:
        lone = 0
        for a in d2[b]:
            if len(d1[a])==1:
                lone+=1
                if lone>1:
                    return False


    used = set()
    for a in d1:
        if a not in used:
            s1,s2,now = {a},d1[a].copy(),d1[a].copy()
            while now:
                b = now.pop()
                da = d2[b]-s1 
                s1|=da 
                for aa in da:
                    db = d1[aa]-s2
                    now|=db
                    s2|=db
            if len(s1)!=len(s2):
                return False
            used|=s1
    return True


