def f(n):
	s = map(int, raw_input().split())
	sm = sum(s)
	if sm %3 != 0:
		return 0
	for i in xrange(1, n):
		s[i] += s[i - 1]
	count = [0] * n
	i = n - 1
	while i > 0:
		if sm/3 == s[-1] - s[i-1]:
			count[i-1] = 1
		i -= 1
	sums = [0] * n
	sums[n-1] = count[n - 1]
	i = n - 2
	while i >= 0:
		sums[i] = sums[i+1]+count[i]
		i -= 1
	count = 0
	for i in xrange(n-2):
		if s[i] == sm/3:
			count += sums[i+1]
	return count
