def weird_odd(c, n, k):

    #print "k = %d" % k
    # initialize odds
    d = {}
    for i in range(k):
        d[i] = Counter()
        odd_boi = None
        for char in c:
            if c[char] % 2 == 1 and odd_boi == None:
                odd_boi = char
        if odd_boi == None:
            for char in c:
                if c[char] > 0:
                    odd_boi = char
                    break
        if odd_boi == None:
            return None
        d[i][odd_boi] = 1
        c[odd_boi] -= 1
    #print d
    #print c
    min_length = n // k
    #print "min_length %d" % min_length
    logging.debug((n, k))
    logging.debug(d)
    for i in d:
        left = min_length - 1
        logging.debug("left = %d" % left) 

        while left > 0:
            for char in c:
                if left == 0:
                    break
                if c[char] == 0:
                    continue
                if c[char] >= left:
                    d[i][char] += left
                    c[char] -= left
                    left = 0
                else:
                    left -= c[char]
                    d[i][char] += c[char]
                    c[char] = 0
        #print d[i]
    #print d
    def make_pal(counts):
        odd_boi = [c for c in counts if counts[c] % 2 == 1]
        #print odd_boi
        if len(odd_boi) > 1:
            return None 
        odd_boi = odd_boi[0]
        s = str(odd_boi * counts[odd_boi])
        counts[odd_boi] = 0
        for c in counts:
            l = counts[c] / 2
            s = l*c + s + l*c
        return s

    #print k, d
    words = []
    for i in d:
        w = make_pal(d[i])
        if w == None:
            return None
        words.append(w)
    return " ".join(words)


