import math
def getSum(n): 
    sum = 0
    while(n > 0): 
        sum += int(n%10) 
        n = int(n/10) 

    return sum

def isPowerOfTwo (x): return (x and (not(x & (x - 1))) )

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x
def egcd(a, b):  
    if a == 0 :   
        return b, 0, 1
    gcd, x1, y1 = egcd(b%a, a)
    x = y1 - (b//a) * x1  
    y = x1  

    return gcd, x, y 

def checkPrime(n) : # Check Prime Number or not 
    if (n <= 1) : return False
    if (n <= 3) : return True
    if (n % 2 == 0 or n % 3 == 0) : return False
    i = 5
    while(i * i <= n) : 
        if (n % i == 0 or n % (i + 2) == 0) : 
            return False
        i = i + 6
    return True
def fib(n):
    if n==0:
        return (0,1)
    p=fib(n>>1)
    c=p[0]*(2*p[1]-p[0])
    d=p[0]*p[0]+p[1]*p[1]
    if (n&1):
        return c+2*d 
    else:
        return c+d 
