def dfs(x,y,prex=0,prey=0) :
    visited[x][y]=True
    for dx,dy in [(-1,0),(1,0),(0,-1),(0,1)] :
        nxtx,nxty=x+dx,y+dy
        if not (0<=nxtx<n and 0<=nxty<m and dmatrix[nxtx][nxty]==dmatrix[x][y]) :
            continue
        if visited[nxtx][nxty] :
            if nxtx!=prex or nxty!=prey : #avoid going back
                return True
        else :
            if dfs(nxtx,nxty,x,y) :
                return True
    return False

