  P = []
  p = 2

  while p < X:
    if E[p]:
      P += [p]
      x = p
      while x<X:
        E[x] = 0
        x += p
    p += 1

  LP = len(P)

  Cm = {}
  CM = {}


  M = 1e30

  for a in sorted(A):
    if a >= M:
      break
    b = a
