import math
import sys
import os
def low( a , b):
	if(a<b):
		return a
	return b

def main():
	T = raw_input()
	S = T.split()
	plus = S.count('+')
	min =  S.count('-')
	N = S[-1]
	N = int(N)
	L1 = []
	L2 = []
	if((plus+1)*N-min<N or (plus+1) - N * min>N  ):
		print 'Impossible'
		return 0
	else:
		plus = plus + 1
		for x in range(0,plus):
			L1.append(1)
		for x in range(0,min):
			L2.append(1)

		while( sum(L1) - sum(L2)  < N ):
			for x in range(0,len(L1)):
				if(L1[x]<N):
					break
			L1[x] = L1[x]+ low(N-L1[x],N - int(sum(L1)) + int(sum(L2)))
		while( sum(L1) - sum(L2)  > N ):
			for x in range(0,len(L2)):
				if(L2[x]<N):
					break
			L2[x] = L2[x]+ low(N-L2[x],int(sum(L1)-sum(L2)) - N)

	out = ''
	last = 0

	for i in range(0, len(T)):
		if (T[i] != '?'):
			out = out + T[i]
			if (T[i] == '+'):
				last = 0
			elif (T[i] == '-'):
				last = 1
		else:
			if (last == 0):
				out = out + str(L1[-1])
				L1.pop()
			else:
				out = out + str(L2[-1])
				L2.pop()
	print 'Possible'
	print out


