def cross(i, j, v, n):
	v[i*n+j] = '.'
	if v[(i+1)*n+j] == '#':
		v[(i+1)*n+j] = '.'
		if v[(i+2)*n+j] == '#':
			v[(i+2)*n+j] = '.'
			if v[(i+1)*n+j+1] == '#':
				v[(i+1)*n+j+1] = '.'
				if v[(i+1)*n+j-1] == '#':
					v[(i+1)*n+j-1] = '.'
					return True
				else:
					return False
			else:
				return False
		else:
			return False
	else:
		return False


