	other=[0]*(s+1)
	for i in xrange(2, s+1):
		if not is_not_prime[i]:
			prime.append(i)
			small[i]=i
			cnt[i]=1
			other[i]=1
		for p in prime:
			next=p*i
			if next>s:
				break
			is_not_prime[next]=True
			small[next]=p
			if i%p==0:
				cnt[next]=cnt[i]+1
				other[next]=other[i]
				break
			cnt[next]=1
			other[next]=i
	print>>sys.stderr, len(prime)
	return small, cnt, other
def add(value):
	any=False
	back_up=value
	while value!=1:
		old=d.get(small[value], (0, 0))
		if old[0]<cnt[value]:
			d[small[value]]=(cnt[value], 0)
			any=True
		value=other[value]
	if any:
		value=back_up
		while value!=1:
			old=d[small[value]]
			if old[0]==cnt[value]:
				d[small[value]]=(old[0], old[1]+1)
			value=other[value]
	return any
def test(value):
	any=False
	while value!=1:
		old=d[small[value]]
		if old[0]==cnt[value] and old[1]==1:
			any=True
		value=other[value]
	return any
