def f(n, arr):
	if n >= len(arr):
		return len(set(arr))
	tails = []
	while(n):
		l = len(tails)
		for i in range(len(arr)):
			lo,hi = 0, len(tails) - 1
			while(lo < hi):
				med = (lo + hi)/ 2
				if tails[med] >= arr[i]:
					hi = med
				else:
					lo = med + 1
			if lo < len(tails) and tails[lo] >= arr[i]: tails[lo] = arr[i]
			else: tails.append(arr[i])
		if len(tails) == l: break
		if len(tails) >= len(arr): break
		n-= 1
	return len(tails)
