def decompose(number):
    prime_factors = []
    while number % 2 == 0:
        prime_factors.append(2)
        number = number / 2
    for i in range(3, int(number**(1/2)) + 1, 2):
        while number % i == 0:
            prime_factors.append(int(i))
            number = number / i
    if number > 2:
        prime_factors.append(int(number))
    return prime_factors

def check_double(A):
    S = set(A)
    my_dict = {x: A.count(x) for x in S if A.count(x)>1}
    try:
        return max(my_dict.keys(), key=(lambda k: my_dict[k]))
    except ValueError:
        return False

def prod(L):
    result = 1
    for x in L:
        result *= x
    return result

for _ in range(int(input())):
    n = int(input())
    prems = decompose(n)
    comp = check_double(prems)
    if comp == False:
        print(1, n, sep='\n')
    else:
        remainder = int(comp*prod([prem for prem in prems if prem != comp]))
        count = prems.count(comp)
        print(count, end='\n')
        for k in range(count-1):
            print(comp, end=' ')
        print(remainder, end='\n')

