def form_teams(g, colors, c, s):
#    print(f'{s = }, {c = }')
    colors[s] = c
    for v in g[s]:
        if colors[v] is None:
            form_teams(g, colors, 1 - c, v)
        elif colors[v] == c:
            colors[s] = -1


def solve(n, m, g):
    colors = [None] * (n + 1)
    for i in range(1, n + 1):
        if colors[i] == None:
            form_teams(g, colors, 0, i)
#    print(colors)
    cont = colors.count(-1)
    if (n - cont) % 2 == 0:
        return cont
    else:
        return cont + 1


