def find_k_smallest(A,k):

    temp=A
    for j in range(k):
        min_el = A[0]
        min_ind = 0
        for ind,el in enumerate(temp):
            if el> min_el:
                min_el= el
                min_ind = ind

        temp[min_ind] = -float('inf')

    return min_ind,min_el


