import math

def smallestDivisor(n): 

    if (n % 2 == 0): 
        return 2; 
    i = 3;  
    while(i * i <= n): 
        if (n % i == 0): 
            return i; 
        i += 2; 

    return n; 

def prevPowerofK(n, k):

    p = int(math.log(n) / math.log(k))
    return int(math.pow(k, p))

def primeFactors(n): 
    l = []
    while n % 2 == 0: 
        l.append(2) 
        n = n // 2

    for i in range(3,int(math.sqrt(n))+1,2): 
        while n % i== 0: 
            l.append(i)
            n = n // i 

    if n > 2: 
        l.append(n)
    return l
